REV.page({"course":"english2","id":"w11","title":"Quantifiers, contrast words, vocabulary and connecting ideas","summary":"How English talks about quantity (many, much, a few, little, some, any, all, most, both, each …), how contrast words and connectors join ideas within and between sentences, and where English words come from: morphemes and affixes, word-formation processes, Greek and Latin parts, and words borrowed from many languages.","n":11,"lectures":[{"code":"11.1","title":"Quantifiers in english- part 1","video":"z-ILfHZhyc8","seconds":1485},{"code":"11.2","title":"Quantifiers in english- part 2","video":"hAOxHB_bJVQ","seconds":1872},{"code":"11.3","title":"Contrast words","video":"pLPzXo8xgBA","seconds":1011},{"code":"11.4","title":"English vocabulary-01","video":"KGGeRd7Y-98","seconds":2479},{"code":"11.5","title":"English vocabulary - 02","video":"oLZoS0mwhW8","seconds":1826},{"code":"11.6","title":"Connecting ideas between & within sentences","video":"ZXWMfaRd-AI","seconds":1665},{"code":"11.7","title":"Innovation in vocabulary","video":"hU5teiNueck","seconds":2107},{"code":"11.8","title":"Advanced vocabulary","video":"pBpCNFpgzXQ","seconds":1546}],"toc":[{"id":"at-a-glance","level":2,"title":"At a glance"},{"id":"quantifiers-how-much-and-how-many","level":2,"title":"Quantifiers: how much and how many"},{"id":"countable-and-uncountable-nouns","level":3,"title":"Countable and uncountable nouns"},{"id":"three-more-facts-about-quantifiers","level":3,"title":"Three more facts about quantifiers"},{"id":"many-and-much-large-quantities","level":2,"title":"Many and much: large quantities"},{"id":"many-with-countable-nouns","level":3,"title":"Many, with countable nouns"},{"id":"more-constructions-with-many","level":3,"title":"More constructions with many"},{"id":"much-with-uncountable-nouns","level":3,"title":"Much, with uncountable nouns"},{"id":"more-constructions-with-much","level":3,"title":"More constructions with much"},{"id":"a-lot-of-and-lots-of-with-both-kinds-of-noun","level":3,"title":"A lot of and lots of, with both kinds of noun"},{"id":"small-quantities-a-few-few-a-little-little-a-bit","level":2,"title":"Small quantities: a few, few, a little, little, a bit"},{"id":"more-uses-of-a-little","level":3,"title":"More uses of a little"},{"id":"a-bit","level":3,"title":"A bit"},{"id":"enough-plenty-and-more-sufficient-amounts","level":2,"title":"Enough, plenty and more: sufficient amounts"},{"id":"some-and-any-non-specific-amounts","level":2,"title":"Some and any: non-specific amounts"},{"id":"all-no-more-most-and-less","level":2,"title":"All, no, more, most and less"},{"id":"all-and-no","level":3,"title":"All and no"},{"id":"more","level":3,"title":"More"},{"id":"most","level":3,"title":"Most"},{"id":"less","level":3,"title":"Less"},{"id":"several-both-either-neither-each-and-every","level":2,"title":"Several, both, either, neither, each and every"},{"id":"both-either-and-neither-two-people-or-things","level":3,"title":"Both, either and neither: two people or things"},{"id":"each-and-every","level":3,"title":"Each and every"},{"id":"contrast-words","level":2,"title":"Contrast words"},{"id":"but","level":3,"title":"But"},{"id":"although-and-though","level":3,"title":"Although and though"},{"id":"even-though","level":3,"title":"Even though"},{"id":"however","level":3,"title":"However"},{"id":"despite-and-in-spite-of","level":3,"title":"Despite and in spite of"},{"id":"words-and-morphemes","level":2,"title":"Words and morphemes"},{"id":"words-keep-changing","level":3,"title":"Words keep changing"},{"id":"breaking-a-word-into-parts","level":3,"title":"Breaking a word into parts"},{"id":"the-classification-of-morphemes","level":3,"title":"The classification of morphemes"},{"id":"free-morphemes","level":3,"title":"Free morphemes"},{"id":"bound-morphemes","level":3,"title":"Bound morphemes"},{"id":"affixes-by-position-prefix-infix-suffix","level":3,"title":"Affixes by position: prefix, infix, suffix"},{"id":"affixes-by-function-derivational-and-inflectional","level":3,"title":"Affixes by function: derivational and inflectional"},{"id":"derivational-affixes-by-the-word-they-make","level":3,"title":"Derivational affixes, by the word they make"},{"id":"word-formation-processes","level":2,"title":"Word-formation processes"},{"id":"clipping","level":3,"title":"Clipping"},{"id":"acronymy","level":3,"title":"Acronymy"},{"id":"blending","level":3,"title":"Blending"},{"id":"back-formation","level":3,"title":"Back-formation"},{"id":"borrowing","level":3,"title":"Borrowing"},{"id":"coinage","level":3,"title":"Coinage"},{"id":"compounding","level":3,"title":"Compounding"},{"id":"inflection-and-derivation","level":3,"title":"Inflection and derivation"},{"id":"connecting-ideas-within-and-between-sentences","level":2,"title":"Connecting ideas within and between sentences"},{"id":"between-sentences-adverbs-and-prepositional-phrases","level":3,"title":"Between sentences: adverbs and prepositional phrases"},{"id":"within-a-sentence-conjunctions","level":3,"title":"Within a sentence: conjunctions"},{"id":"connecting-two-clauses","level":3,"title":"Connecting two clauses"},{"id":"connectors-by-function","level":3,"title":"Connectors by function"},{"id":"even-though-even-so-however","level":3,"title":"Even though, even so, however"},{"id":"innovation-in-vocabulary","level":2,"title":"Innovation in vocabulary"},{"id":"prefixes-and-suffixes-from-greek-and-latin","level":3,"title":"Prefixes and suffixes from Greek and Latin"},{"id":"words-from-foreign-languages","level":3,"title":"Words from foreign languages"},{"id":"instilingo-the-code-of-iit-madras","level":3,"title":"Instilingo: the code of IIT Madras"},{"id":"new-media","level":3,"title":"New media"},{"id":"advanced-vocabulary-loanwords","level":2,"title":"Advanced vocabulary: loanwords"},{"id":"words-from-latin","level":3,"title":"Words from Latin"},{"id":"words-from-french","level":3,"title":"Words from French"},{"id":"words-from-italian","level":3,"title":"Words from Italian"},{"id":"words-from-japanese","level":3,"title":"Words from Japanese"},{"id":"summary","level":2,"title":"Summary"},{"id":"check-yourself","level":2,"title":"Check yourself"}],"html":"<h2 id=\"at-a-glance\">At a glance</h2>\n<ul>\n<li><strong>Quantifiers</strong> (11.1, 11.2): words such as <em>many, much, a few, little, some, any, all, most, less, both, either, each</em>. They tell <strong>how many</strong> (with countable nouns) or <strong>how much</strong> (with uncountable nouns). They are a kind of determiner; without a noun they work as pronouns (<em>No, there aren’t any</em>).</li>\n<li><strong>Large, small, sufficient, non-specific</strong> (11.1, 11.2): <em>many</em> + countable, <em>much</em> + uncountable, <em>a lot of / lots of</em> + both. <em>A few, a little</em> are positive (“some”); <em>few, little</em> are negative (“hardly any”). <em>Enough, plenty, loads of</em> = enough or more. <em>Some</em> in affirmative sentences, <em>any</em> in negatives and questions.</li>\n<li><strong>Agreement</strong> (11.2): <em>both</em> takes a plural verb; <em>either, neither, each, every</em> take a singular verb.</li>\n<li><strong>Contrast words</strong> (11.3): <em>but, although, though, even though, however, despite, in spite of</em> join a result to an expectation that it opposes. <em>Although, though, even though</em> + a clause; <em>despite, in spite of</em> + a phrase; never <em>despite of</em>.</li>\n<li><strong>Morphemes</strong> (11.4): the smallest units with a meaning or a grammatical job. <strong>Free</strong> morphemes stand alone (lexical: open class; functional: closed class). <strong>Bound</strong> morphemes do not (bound roots and affixes). <strong>Derivational</strong> affixes make new words; the <strong>eight inflections</strong> only make grammatical forms of the same word.</li>\n<li><strong>Word-formation processes</strong> (11.5): clipping (<em>exam</em>), acronymy (<em>NATO</em>), blending (<em>brunch</em>), back-formation (<em>resurrect</em>), borrowing (<em>loot</em>), coinage (<em>xerox</em>), compounding (<em>lipstick</em>), inflection (<em>goes</em>), derivation (<em>kindness</em>).</li>\n<li><strong>Connecting ideas</strong> (11.6): adverbs and prepositional phrases connect ideas <strong>between</strong> sentences (<em>as a result, alternatively, even so</em>); conjunctions connect them <strong>within</strong> a sentence (<em>while, so that, even though</em>). Between two clauses, write <em>; however,</em>.</li>\n<li><strong>Vocabulary from many sources</strong> (11.7, 11.8): Greek and Latin prefixes and suffixes (<em>hydro-, hyper-, -cide, -logy</em>); English has words from about 120 languages; IIT Madras’s own <em>instilingo</em>; new-media words and acronyms; Latin, French, Italian and Japanese loanwords (<em>bona fide, faux pas, vendetta, tsunami</em>).</li>\n</ul>\n<h2 id=\"quantifiers-how-much-and-how-many\">Quantifiers: how much and how many</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>Words that describe <strong>quality</strong> (what something is like: <em>big, red, honest</em>) are <strong>adjectives</strong>. Words that describe <strong>quantity</strong> (how much or how many there is) are <strong>quantifiers</strong> (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=30s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 0:30</a>). Compare:</p>\n<ul>\n<li><em>Do you want water?</em> (nothing about the amount)</li>\n<li><em>Do you want <strong>some</strong> water?</em> (an amount, though not an exact one)</li>\n</ul>\n<p>Quantifiers are simple, common words. A closer look at them helps us write and speak “with accuracy and confidence” (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=30s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 0:30</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=150s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:30</a>). There is no closed list of them: the lectures discuss the common ones, and we have to watch for others in use (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=180s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:00</a>).</p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Quantifier</span></div><div class=\"box-b\">\n<p>The slide “What are quantifiers?” (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=133s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:13</a>):</p>\n<ul>\n<li>They are a sub-group of <strong>determiners</strong> and thus, their function is to introduce a <strong>noun phrase</strong> in a sentence.</li>\n<li>They are words or phrases that specify ‘<strong>how much</strong>’ or ‘<strong>how many</strong>’ of the noun there is.</li>\n</ul>\n<p>A <strong>determiner</strong> is a word that comes before a noun and tells which one or how much: <em>a, the, this, my, some, all</em>. A <strong>noun phrase</strong> is a noun together with the words that go with it: <em>some water</em>, <em>all the four eggs</em>.</p>\n</div></section>\n<h3 id=\"countable-and-uncountable-nouns\">Countable and uncountable nouns</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Countable and uncountable nouns</span></div><div class=\"box-b\">\n<ul>\n<li>A <strong>countable noun</strong> names things we can count: <em>one child, two children; a guest, ten guests</em>. It has a plural form. We ask <strong>how many?</strong></li>\n<li>An <strong>uncountable noun</strong> names a mass or an idea that we do not count: <em>water, money, time, work, information, music</em>. It has no plural form. We ask <strong>how much?</strong></li>\n</ul>\n</div></section>\n<p>The lecturer writes it on the slide: <em>how much</em> → uncountable, <em>how many</em> → countable (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=270s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:30</a>).</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>The noun</th>\n<th>The question it answers</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Do you want <strong>some</strong> water?</td>\n<td><em>water</em>: uncountable</td>\n<td>How much water?</td>\n</tr>\n<tr>\n<td><strong>All</strong> children must go for the drill.</td>\n<td><em>children</em>: countable</td>\n<td>How many children?</td>\n</tr>\n</tbody>\n</table></div>\n<p>In both sentences the quantifier stands before the noun and describes it, so the lecturer marks it “Adj”: here it works like an <strong>adjective</strong> (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=180s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:00</a>).</p>\n<h3 id=\"three-more-facts-about-quantifiers\">Three more facts about quantifiers</h3>\n<p>The slides “Continued…” (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=338s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:38</a>, <a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=430s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 7:10</a>):</p>\n<ol>\n<li><strong>They may be used without a noun.</strong> Then they act as <strong>pronouns</strong> (a pronoun is a word that stands for a noun).\n<ul>\n<li><em>Are there <strong>any</strong> guests left to enter the hall?</em> Here <em>any</em> is a determiner, before the noun <em>guests</em>.</li>\n<li><em>No, there aren’t <strong>any</strong>.</em> Here <em>any</em> stands alone and means “any guests”: a pronoun. The lecturer calls this the <strong>pronominal</strong> use (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=390s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:30</a>).</li>\n</ul>\n</li>\n<li><strong>They can combine with other determiners</strong> to make the noun reference clearer: <em><strong>All</strong> the <strong>four</strong> eggs were bad.</em> (<em>All</em>, <em>the</em> and <em>four</em> all come before <em>eggs</em>.)</li>\n<li><strong>They are used with both countable and uncountable nouns</strong>, for <strong>large</strong>, <strong>small</strong> and <strong>undefined</strong> quantities, and also for <strong>sufficient</strong> quantities:\n<ul>\n<li><em>He has <strong>lots of</strong> friends.</em> (countable)</li>\n<li><em>The troupe has got <strong>no</strong> money.</em> (uncountable; a <strong>troupe</strong> is a group of performers, such as dancers or actors)</li>\n</ul>\n</li>\n</ol>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Read it twice</span></div><div class=\"box-b\">\n<p>The lecturer’s exercise (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=750s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 12:30</a>): read a sentence <strong>without</strong> its quantifier, then <strong>with</strong> it, and see how the meaning changes. <em>People are concerned about climate change</em> says something very different from <em>Not many people are concerned about climate change</em>.</p>\n</div></section>\n<h2 id=\"many-and-much-large-quantities\">Many and much: large quantities</h2>\n<h3 id=\"many-with-countable-nouns\">Many, with countable nouns</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Many</span></div><div class=\"box-b\">\n<p><em>Many</em> is used with <strong>countable</strong> nouns (in the plural) for a large number. The slide (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=504s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 8:24</a>) labels each example by the kind of sentence. An <strong>interrogative</strong> sentence asks a question; a <strong>negative</strong> sentence has <em>not</em> or <em>no</em>; an <strong>affirmative</strong> sentence states something positively.</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Kind of sentence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Were there <strong>many</strong> visitors in the park?</td>\n<td>interrogative</td>\n</tr>\n<tr>\n<td>We are a small group. We don’t have <strong>many</strong> team members.</td>\n<td>negative</td>\n</tr>\n<tr>\n<td><strong>Many</strong> workers were trapped inside the mines.</td>\n<td>affirmative and formal</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Many and much in everyday speech (my note)</span></div><div class=\"box-b\">\n<p>The slides mark the affirmative use of <em>many</em> and <em>much</em> as <strong>formal</strong>. In everyday speech, people usually say <em>a lot of</em> in affirmative sentences (<em>We have a lot of team members</em>) and keep <em>many</em> and <em>much</em> for questions and negatives. In formal writing, <em>many</em> and <em>much</em> are fine everywhere.</p>\n</div></section>\n<h3 id=\"more-constructions-with-many\">More constructions with many</h3>\n<p>The slides “Other possible constructions and combinations of <em>Many</em>” (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=565s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:25</a>) and “<em>Many</em> with other modifiers” (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=671s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:11</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Construction</th>\n<th>The slide’s example</th>\n<th>What it means</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>not many</strong></td>\n<td><strong>Not many</strong> people are concerned about climate change.</td>\n<td>few: <em>many</em> with <em>not</em> has the meaning <em>few</em></td>\n</tr>\n<tr>\n<td><strong>many of</strong></td>\n<td><strong>Many of</strong> her friends have settled abroad.</td>\n<td>a large part of a particular group (affirmative and formal)</td>\n</tr>\n<tr>\n<td><strong>many</strong> + noun + <em>who …</em></td>\n<td>There are <strong>many</strong> children who have never had a comfortable life.</td>\n<td>formal; <em>who have never had …</em> is a relative clause</td>\n</tr>\n<tr>\n<td><strong>as many as</strong> + number</td>\n<td><strong>As many as</strong> two thousand people gathered to listen to the leader.</td>\n<td>a shockingly or surprisingly high number</td>\n</tr>\n<tr>\n<td><strong>in as many</strong> + noun</td>\n<td>She is a very honest officer. She has won ten medals <strong>in as many</strong> years.</td>\n<td>in the same number of (ten medals in ten years)</td>\n</tr>\n<tr>\n<td><strong>very many</strong></td>\n<td><strong>Very many</strong> people do not understand the true value of organic farming.</td>\n<td>a very large number</td>\n</tr>\n<tr>\n<td><strong>so many</strong></td>\n<td>Why do <strong>so many</strong> people eat junk food?</td>\n<td><em>so</em> makes <em>many</em> stronger</td>\n</tr>\n<tr>\n<td><strong>a great many</strong></td>\n<td>There are <strong>a great many</strong> studies on why soft drinks are bad for health.</td>\n<td>a very large number</td>\n</tr>\n<tr>\n<td><strong>too many</strong></td>\n<td>There were <strong>too many</strong> complaints about the product.</td>\n<td>more than is acceptable</td>\n</tr>\n</tbody>\n</table></div>\n<p>A <strong>relative clause</strong> describes a noun and begins with <em>who, which</em> or <em>that</em> (<a href=\"#/english2/w03/the-adjectival-relative-clause\">Week 3</a>). A <strong>modifier</strong> is a word that changes or limits the meaning of another word; <em>very, so, too</em> are <strong>intensifiers</strong>, modifiers that make a word stronger.</p>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">A slip on the slide</span></div><div class=\"box-b\">\n<p>The slide writes “There are great many studies”. The fixed phrase is <em><strong>a</strong> great many</em>: <em>There are a great many studies …</em></p>\n</div></section>\n<h3 id=\"much-with-uncountable-nouns\">Much, with uncountable nouns</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Much</span></div><div class=\"box-b\">\n<p><em>Much</em> is used with <strong>uncountable</strong> nouns for a large amount (the slide, <a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=774s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 12:54</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Kind of sentence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>I do not have <strong>much</strong> time to spare. Could you make it faster?</td>\n<td>negative</td>\n</tr>\n<tr>\n<td>Is there <strong>much</strong> work left?</td>\n<td>interrogative</td>\n</tr>\n<tr>\n<td>There is <strong>much</strong> talk about the new mall among the residents of the town.</td>\n<td>affirmative and formal</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Much time, but many times</span></div><div class=\"box-b\">\n<p><em>Time</em> (what a clock measures) is uncountable: <em>much time</em>, never ✗ <em>many time</em>. But <em>time</em> can also mean “an occasion”, and then it is countable: <em>many times</em>, <em>many a time</em> (= often; <em>many a</em> takes a singular noun). As the lecturer says, with <em>many</em> “we are not talking about time, we are talking about repetition” (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=810s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:30</a>).</p>\n</div></section>\n<h3 id=\"more-constructions-with-much\">More constructions with much</h3>\n<p>The slides (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=871s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 14:31</a>, <a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=962s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:02</a>, <a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1028s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:08</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Construction</th>\n<th>The slide’s example</th>\n<th>What it means</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>so much</strong> (<em>so</em> as an intensifier)</td>\n<td>It’s been long since I met you. I have <strong>so much</strong> to talk about.</td>\n<td>a very large amount</td>\n</tr>\n<tr>\n<td><strong>much of</strong></td>\n<td>How <strong>much of</strong> the news is true? / The artist lived <strong>much of</strong> his life in a small town in Yorkshire.</td>\n<td>a large part of something particular</td>\n</tr>\n<tr>\n<td><strong>too much</strong></td>\n<td>Some speakers make <strong>too much</strong> noise.</td>\n<td>more than necessary</td>\n</tr>\n<tr>\n<td><strong>as much … as</strong> (comparisons of quantity)</td>\n<td>You must try to collect <strong>as much</strong> information <strong>as</strong> you can.</td>\n<td>equal in amount or degree</td>\n</tr>\n<tr>\n<td><strong>as much as</strong></td>\n<td>Her income is <strong>as much as</strong> his.</td>\n<td>an amount as large as another</td>\n</tr>\n<tr>\n<td><strong>much</strong> + comparative</td>\n<td>I walk <strong>much</strong> more slowly after the accident. / She can read <strong>much</strong> better with the glasses.</td>\n<td>a lot (more slowly, better)</td>\n</tr>\n<tr>\n<td><strong>this / that much</strong> (spoken English)</td>\n<td>I had only <strong>that much</strong> time to finish the task. / My sister gave me just <strong>this much</strong> space on the bench.</td>\n<td>this or that amount (often with a gesture)</td>\n</tr>\n</tbody>\n</table></div>\n<p>A <strong>comparative</strong> is the form of an adjective or adverb that compares: <em>better, more slowly, brighter</em>.</p>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Small fixes to the slides</span></div><div class=\"box-b\">\n<ul>\n<li>The slide’s <em>so much</em> sentences read “It’s been long since I have met you. I have so much talk to do”; the lecturer also says “so much to talk”. The natural forms are <em>It’s been long since I met you. I have so much to talk about.</em></li>\n<li>In “as much information as they can” the lecturer corrects <em>they</em> to <em>you</em> in pen (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=962s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:02</a>).</li>\n<li>The slide has “as much as him”; the lecturer reads it as “as much as his income”, so <em>as much as his</em>.</li>\n<li>The slide’s third <em>as much as</em> example, “Dev completed as much as his work”, is marked “(almost but not quite)”: Dev’s work is nearly, but not quite, complete (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=990s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:30</a>). The wording is unusual; <em>Dev has almost completed his work</em> says the same plainly.</li>\n</ul>\n</div></section>\n<h3 id=\"a-lot-of-and-lots-of-with-both-kinds-of-noun\">A lot of and lots of, with both kinds of noun</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">A lot of, lots of</span></div><div class=\"box-b\">\n<p>“The expression <em>a lot of</em> and <em>lots of</em> can be with both countable and uncountable nouns” (the slide, <a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1099s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:19</a>).</p>\n<ul>\n<li>They have got <strong>a lot of</strong> money. (uncountable)</li>\n<li>The dancers wore <strong>a lot of</strong> bangles. (countable)</li>\n<li>The reservoir can hold <strong>lots of</strong> water. (uncountable)</li>\n<li>The jury may not give us <strong>lots of</strong> time. (uncountable)</li>\n</ul>\n</div></section>\n<h2 id=\"small-quantities-a-few-few-a-little-little-a-bit\">Small quantities: a few, few, a little, little, a bit</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>For small amounts English has two pairs, and the tiny word <em>a</em> changes the feeling (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1159s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:19</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=240s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:00</a>):</p>\n<ul>\n<li><strong>with <em>a</em></strong>: a small amount, but <strong>some</strong>: a positive meaning.</li>\n<li><strong>without <em>a</em></strong>: a small amount, <strong>not enough</strong>: “out of many, only a few”, a negative meaning (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=330s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:30</a>).</li>\n</ul>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th></th>\n<th>With countable nouns</th>\n<th>With uncountable nouns</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>positive (“some”)</td>\n<td><strong>a few</strong> teachers</td>\n<td><strong>a little</strong> moisturizer</td>\n</tr>\n<tr>\n<td>negative (“hardly any”)</td>\n<td><strong>few</strong> apples</td>\n<td><strong>little</strong> knowledge</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">A few, few</span></div><div class=\"box-b\">\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1159s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:19</a>); the second lecture repeats it (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=210s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:30</a>):</p>\n<ul>\n<li><em><strong>A few</strong></em> is used with countable nouns: <em>A few teachers will accompany the students on the trip.</em> (Some teachers will go: not many, but some.)</li>\n<li><em><strong>A few of</strong></em> + a particular group: <em>A few of her works are published in Q1 journals.</em> (Q1 journals are the top quarter of journals in a field.)</li>\n<li><em><strong>Few</strong></em> (no article) has a <strong>negative meaning</strong>: <em>Few apples from the shop were good.</em> (Out of all the apples, only a few were good.)</li>\n</ul>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">A little, little</span></div><div class=\"box-b\">\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1264s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:04</a>), repeated in the second lecture (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=367s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:07</a>):</p>\n<ul>\n<li><em><strong>A little</strong></em> is used with uncountable nouns: <em>Rub a little moisturizer on the face for hydration.</em> (Some moisturizer: a small amount.)</li>\n<li><em><strong>A little of</strong></em>: the slide’s example is <em>You must blend the mixture while adding a little of water to it.</em></li>\n<li><em><strong>Little</strong></em> (no article) has a <strong>negative meaning</strong>: <em>Little knowledge is dangerous.</em> (Almost no knowledge.)</li>\n</ul>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">A little of the water (my note)</span></div><div class=\"box-b\">\n<p>In standard English, <em>of</em> comes after <em>a little</em> only before a word such as <em>the, this, my</em>: <em>add a little of the water</em>, or simply <em>add a little water</em>. The same rule appears below with <em>most of the</em> (11.2).</p>\n</div></section>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">A few or few?</span></div><div class=\"box-b\">\n<p>Both mean a small number; the difference is the speaker’s attitude. <em>A few teachers will come</em> is good news (some will come). <em>Few apples were good</em> is bad news (hardly any). The lecture adds that <em>few</em> is also smaller than <em>a few</em> (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1230s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:30</a>). And never use <em>a little</em> with a countable noun: ✗ <em>a little teachers</em>, ✓ <em>a few teachers</em> (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=390s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:30</a>).</p>\n</div></section>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Remember the a</span></div><div class=\"box-b\">\n<p><em>a</em> adds a little something: <em><strong>a</strong> few</em> = “some”, <em>few</em> = “hardly any”. The same holds for <em><strong>a</strong> little</em> and <em>little</em>.</p>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">The proverb (my note)</span></div><div class=\"box-b\">\n<p>The well-known proverb is <em>A <strong>little</strong> knowledge is a dangerous thing</em>. There <em>a little</em> means “some, a small amount”: knowing only a little can make a person overconfident. The slide’s sentence <em>Little knowledge is dangerous</em> has no <em>a</em>, so it means “almost no knowledge”.</p>\n</div></section>\n<h3 id=\"more-uses-of-a-little\">More uses of a little</h3>\n<p>The slide “Other constructions continued…” (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=468s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 7:48</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Use</th>\n<th>The slide’s example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><em>a little</em> as an <strong>adverb</strong> (it describes the verb <em>smiled</em>)</td>\n<td>Their eyes met and the baby smiled at him, <strong>a little</strong>.</td>\n</tr>\n<tr>\n<td><em>a little</em> with adverbs and adjectives, as a <strong>modifier</strong> (formal)</td>\n<td>Seema has to try <strong>a little</strong> more to clear the interview. / Try and make the painting <strong>a little</strong> better than the last time.</td>\n</tr>\n<tr>\n<td><em>a little</em> with <em>bit</em></td>\n<td>It was <strong>a little bit</strong> difficult to agree with his demands.</td>\n</tr>\n</tbody>\n</table></div>\n<p><em>A little</em> already means “a bit”; adding <em>bit</em> “downsizes the impact” even more (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=510s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 8:30</a>). <em>A little bit difficult</em> is a softer way to say <em>difficult</em>.</p>\n<h3 id=\"a-bit\">A bit</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">A bit</span></div><div class=\"box-b\">\n<p>“<em>A bit</em> [can] be used to refer to both <strong>concrete</strong> and <strong>abstract</strong> things but in different forms” (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=545s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:05</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=654s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:54</a>). Concrete things can be seen and touched (<em>paper, weight</em>); abstract things are ideas and feelings (<em>help, advice</em>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>What <em>a bit</em> does</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>I was <strong>a bit</strong> bored at the concert.</td>\n<td>modifies the adjective <em>bored</em> (informal)</td>\n</tr>\n<tr>\n<td>The day was <strong>a bit</strong> brighter than yesterday.</td>\n<td>modifies the comparative adjective <em>brighter</em></td>\n</tr>\n<tr>\n<td>There were <strong>bits of</strong> paper lying on the floor.</td>\n<td>small pieces (concrete)</td>\n</tr>\n<tr>\n<td>Frank gave him <strong>a few bits of</strong> advice on how to prepare for the test.</td>\n<td>softens the language; informal</td>\n</tr>\n<tr>\n<td>I need <strong>a bit of</strong> help from you.</td>\n<td>abstract</td>\n</tr>\n<tr>\n<td>I think I have lost <strong>a bit of</strong> weight. Haven’t I?</td>\n<td>concrete</td>\n</tr>\n</tbody>\n</table></div>\n<p><em>A bit bored</em> is “a nicer way of saying I was bored” (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=570s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:30</a>): it softens what we say.</p>\n<h2 id=\"enough-plenty-and-more-sufficient-amounts\">Enough, plenty and more: sufficient amounts</h2>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Quantifiers for a sufficient amount</span></div><div class=\"box-b\">\n<p>“Most of them can be used with both countable and uncountable nouns” (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=676s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:16</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=773s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 12:53</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Quantifier</th>\n<th>Meaning</th>\n<th>The slide’s example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>enough</strong></td>\n<td>as much as is needed</td>\n<td>We have <strong>enough</strong> food for the evening. (We need not cook more.)</td>\n</tr>\n<tr>\n<td><strong>plenty (of)</strong></td>\n<td>a lot; enough or more</td>\n<td>Should we buy more bread? No, there’s <strong>plenty</strong>. / Anita has <strong>plenty of</strong> toys.</td>\n</tr>\n<tr>\n<td><strong>heaps of</strong></td>\n<td>a large amount</td>\n<td>We have <strong>heaps of</strong> cookies at our home.</td>\n</tr>\n<tr>\n<td><strong>loads of</strong></td>\n<td>a large amount</td>\n<td>There is <strong>loads of</strong> time left for my trip to Shimla.</td>\n</tr>\n<tr>\n<td><strong>a load of</strong></td>\n<td>a large amount</td>\n<td>Make it quick. You have <strong>a load of</strong> work to be finished before the weekend.</td>\n</tr>\n</tbody>\n</table></div>\n<p>The lecturer’s point is <strong>intensity</strong>, the strength of the word (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=810s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:30</a>). <em>There is enough time</em> and <em>There is loads of time</em> are both correct, but they create a different impact. “Though <em>plenty</em> means a lot”, it still has the reading of sufficiency; <em>heaps of, loads of, a load of</em> say a little more: plenty and more (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=780s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:00</a>). Choose the word whose strength fits what you mean.</p>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Informal words (my note)</span></div><div class=\"box-b\">\n<p><em>Heaps of, loads of</em> and <em>a load of</em> are informal. In formal writing, use <em>a large amount of, many</em> or <em>much</em>.</p>\n</div></section>\n<h2 id=\"some-and-any-non-specific-amounts\">Some and any: non-specific amounts</h2>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Some</span></div><div class=\"box-b\">\n<p>The slide “Quantifiers used with non-specific amounts” (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=863s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 14:23</a>):</p>\n<ul>\n<li>It is used to refer to a <strong>non-specific</strong> amount of something (an amount that we do not state exactly).</li>\n<li>It is mostly used in <strong>affirmative</strong> sentences.</li>\n<li>It can be used with <strong>plural</strong> nouns and <strong>uncountable</strong> nouns.</li>\n</ul>\n<p><em>I have <strong>some</strong> money with me.</em> (No amount is stated, but it is not nothing either.) / <em>I would like <strong>some</strong> apples for breakfast.</em></p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Any</span></div><div class=\"box-b\">\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=977s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:17</a>):</p>\n<ul>\n<li>It is used to refer to a non-specific amount of something.</li>\n<li>It is mostly used in <strong>negative</strong> and <strong>interrogative</strong> sentences.</li>\n<li>It can be used with plural nouns and uncountable nouns.</li>\n<li>It is mostly used when the <strong>context is negative</strong>.</li>\n</ul>\n<p><em>Is there <strong>any</strong> milk left?</em> (The expected answer would be a “no”; uncountable noun; interrogative.) / <em>There weren’t <strong>any</strong> cans left in the tray.</em> (Negative sentence; plural noun.)</p>\n</div></section>\n<p>Why is the expected answer “no”? We have already looked, we think nothing is left, and we ask only to confirm (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1020s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:00</a>).</p>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Some in negatives, any in affirmatives</span></div><div class=\"box-b\">\n<p>The lecturer’s pen notes (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1080s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:00</a>):</p>\n<ul>\n<li>✓ <em>I do not have <strong>any</strong> money.</em> ✓ <em>I don’t have money.</em></li>\n<li>✗ <em>I have <strong>any</strong> money.</em> The use of <em>any</em> depends on a negative marker (or a question) in the sentence (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1110s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:30</a>).</li>\n<li><em>I do not have <strong>some</strong> money</em> is grammatical, but it is not how we make the sentence negative: “we usually do not say” it (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=930s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 15:30</a>).</li>\n</ul>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th></th>\n<th>some</th>\n<th>any</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>amount</td>\n<td>non-specific</td>\n<td>non-specific</td>\n</tr>\n<tr>\n<td>kind of sentence</td>\n<td>affirmative</td>\n<td>negative, interrogative</td>\n</tr>\n<tr>\n<td>nouns</td>\n<td>plural, uncountable</td>\n<td>plural, uncountable</td>\n</tr>\n<tr>\n<td>example</td>\n<td>I have some money.</td>\n<td>I don’t have any money. / Is there any milk left?</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"all-no-more-most-and-less\">All, no, more, most and less</h2>\n<h3 id=\"all-and-no\">All and no</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">All, all of</span></div><div class=\"box-b\">\n<p>“<em>All, All (of)</em> to mean <strong>everyone</strong> or <strong>the complete amount</strong>”; used with countable and uncountable nouns (the slide, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1179s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:39</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Note on the slide</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>All (the)</strong> children wrote the exam well.</td>\n<td>countable</td>\n</tr>\n<tr>\n<td><strong>All (of)</strong> the children wrote the exam well.</td>\n<td><em>of</em> in brackets: it may be dropped</td>\n</tr>\n<tr>\n<td><strong>All (of)</strong> this is untrue.</td>\n<td>before <em>this / that / these / those</em></td>\n</tr>\n<tr>\n<td><strong>All of</strong> you must be present at the meet.</td>\n<td>before object personal pronouns</td>\n</tr>\n<tr>\n<td>I love <strong>all</strong> music.</td>\n<td>uncountable (all kinds of music)</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Object personal pronouns</strong> are <em>me, you, him, her, it, us, them</em>.</p>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">All of you</span></div><div class=\"box-b\">\n<p>As the slide’s brackets show, <em>of</em> may be dropped before <em>the</em> and <em>this</em> (<em>all the children, all this</em>), but not before a personal pronoun: ✓ <em>all of you, all of them</em>, ✗ <em>all you must be present</em>.</p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">No</span></div><div class=\"box-b\">\n<p><em>No</em> is a quantifier too: it gives a <strong>zero</strong> quantity and makes the sentence negative. It goes with countable and uncountable nouns (the slide, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1233s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:33</a>).</p>\n<ul>\n<li>There are <strong>no</strong> juice bottles available. (countable)</li>\n<li><strong>No</strong> work is allotted for you today. (uncountable)</li>\n</ul>\n</div></section>\n<h3 id=\"more\">More</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">More</span></div><div class=\"box-b\">\n<p>“<em>More, more (of), more and more</em> to mean <strong>additional</strong> quantities” (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1233s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:33</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1297s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:37</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1319s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:59</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Used with</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Please write to us for <strong>more</strong> details.</td>\n<td>a countable noun</td>\n</tr>\n<tr>\n<td>I can give you <strong>more</strong> information on the material.</td>\n<td>an uncountable noun</td>\n</tr>\n<tr>\n<td>I’m <strong>more</strong> in need of the money.</td>\n<td>a prepositional phrase</td>\n</tr>\n<tr>\n<td>You should drive <strong>more</strong> carefully ahead of a school.</td>\n<td>an adverb</td>\n</tr>\n<tr>\n<td>Tom looked <strong>more</strong> handsome in the tuxedo coat.</td>\n<td>an adjective (comparative)</td>\n</tr>\n<tr>\n<td>If you don’t pay the fee now, you will have to pay <strong>more</strong> later.</td>\n<td>a verb</td>\n</tr>\n<tr>\n<td>Give me <strong>more of</strong> that curry.</td>\n<td><em>this / that / these / those</em></td>\n</tr>\n<tr>\n<td>I want to see <strong>more of</strong> you in the department.</td>\n<td>object personal pronouns</td>\n</tr>\n<tr>\n<td>How many <strong>more of</strong> my pens will you lose?</td>\n<td>possessives</td>\n</tr>\n<tr>\n<td><strong>More and more</strong> people are applying for this job position.</td>\n<td>emphasis on the additional quantity</td>\n</tr>\n</tbody>\n</table></div>\n<p>A <strong>prepositional phrase</strong> is a preposition with the noun phrase after it: <em>in need</em>, <em>of the money</em>, <em>ahead of a school</em>. A <strong>possessive</strong> shows the owner: <em>my, your, his, Ram’s</em>.</p>\n<h3 id=\"most\">Most</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Most, most of, most of the</span></div><div class=\"box-b\">\n<p><em>Most</em> means <strong>the majority</strong>, the largest part (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1327s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:07</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1407s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:27</a>). We say <em>most</em> when “we don’t want to take the responsibility of <em>all</em>” (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1350s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:30</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Note on the slide</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Most</strong> water is fit for consumption.</td>\n<td>uncountable noun</td>\n</tr>\n<tr>\n<td>He meets with her <strong>most</strong> evenings.</td>\n<td>countable</td>\n</tr>\n<tr>\n<td><strong>Most</strong> junk foods are harmful for health.</td>\n<td>“the majority of” junk foods <strong>in general</strong></td>\n</tr>\n<tr>\n<td>The shop was served a notice for serving unhygienic food. <strong>Most of the</strong> unhygienic food was expired junk food.</td>\n<td>“the majority of” unhygienic food <strong>in particular</strong></td>\n</tr>\n<tr>\n<td><strong>Most of</strong> India has a tropical climate.</td>\n<td>before geographical places</td>\n</tr>\n<tr>\n<td><strong>Most of the</strong> work has been completed.</td>\n<td>before the definite article</td>\n</tr>\n<tr>\n<td><strong>Most</strong> work has been completed.</td>\n<td>“‘of’ is used only when ‘most’ is followed by the definite article”</td>\n</tr>\n</tbody>\n</table></div>\n<p>The <strong>definite article</strong> is <em>the</em>. (The slide’s shop sentence drops a word, “The shop was a notice”, and has “food were”; <em>food</em> is uncountable, so <em>was</em>.)</p>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Most, or most of the?</span></div><div class=\"box-b\">\n<p>✓ <em>Most work …</em> (work in general). ✓ <em>Most <strong>of the</strong> work …</em> (a particular piece of work). ✗ <em>Most of work …</em>. Use <em>of</em> only before <em>the</em> (or before a place name such as <em>India</em>).</p>\n</div></section>\n<h3 id=\"less\">Less</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Less, less of, less and less</span></div><div class=\"box-b\">\n<p><em>Less</em> refers to a <strong>reduced</strong> (smaller) quantity or amount (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1416s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:36</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1458s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:18</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Used with</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>This refrigerator consumes <strong>less</strong> power.</td>\n<td>a noun</td>\n</tr>\n<tr>\n<td>The rooms were arranged <strong>less</strong> quickly for the local residents.</td>\n<td>an adverb</td>\n</tr>\n<tr>\n<td>The legs of the chair were <strong>less</strong> steady.</td>\n<td>an adjective</td>\n</tr>\n<tr>\n<td>The tickets <strong>cost less</strong> when booked online.</td>\n<td>a verb</td>\n</tr>\n<tr>\n<td>The law and order situation will improve only if <strong>less of</strong> the criminal activities are supported.</td>\n<td>the article</td>\n</tr>\n<tr>\n<td>There was <strong>less of</strong> them at the shop today.</td>\n<td>object personal pronouns</td>\n</tr>\n<tr>\n<td>He has been studying <strong>less and less</strong>. At this rate, clearing the exams would become a distant dream.</td>\n<td>emphasis on the reduced quantity</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Where less goes</span></div><div class=\"box-b\">\n<p>The slide: “when used with a verb, <em>less</em> follows it (<em>cost less</em>), whereas in all other cases above it precedes” (<em>less power, less quickly, less steady</em>).</p>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Less or fewer (my note)</span></div><div class=\"box-b\">\n<p>In careful writing, many teachers and examiners prefer <em>fewer</em> with plural countable nouns (<em>fewer cans, fewer of them, fewer criminal activities</em>) and keep <em>less</em> for uncountable nouns (<em>less power, less water</em>). The slides’ sentences with <em>them</em> and <em>criminal activities</em> follow everyday speech.</p>\n</div></section>\n<h2 id=\"several-both-either-neither-each-and-every\">Several, both, either, neither, each and every</h2>\n<p>The slide “Other quantifiers used only with countable nouns” (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1469s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:29</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Several</span></div><div class=\"box-b\">\n<p><em>Several</em> means <strong>more than one but not many</strong>, and goes only with countable nouns: <em>There are <strong>several</strong> flaws in the document.</em></p>\n</div></section>\n<h3 id=\"both-either-and-neither-two-people-or-things\">Both, either and neither: two people or things</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Both, both of</span></div><div class=\"box-b\">\n<p>“<em>Both, either</em> and <em>neither</em> to talk about <strong>two</strong> people or things.” <em>Both</em> and <em>both of</em> are “used always with a <strong>plural</strong> verb” (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1469s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:29</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1516s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 25:16</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Note on the slide</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>She teaches <strong>both</strong> my children. / She teaches <strong>both of</strong> my children.</td>\n<td>both / both of + possessive + noun</td>\n</tr>\n<tr>\n<td>I returned <strong>both</strong> books to the library.</td>\n<td>with a noun</td>\n</tr>\n<tr>\n<td>They <strong>both</strong> are from the same department.</td>\n<td>with a subject pronoun</td>\n</tr>\n<tr>\n<td><strong>Both of</strong> them are from the same department.</td>\n<td>with an object pronoun</td>\n</tr>\n<tr>\n<td>Two students have come to the office. <strong>Both</strong> were from the same department.</td>\n<td>as a pronoun</td>\n</tr>\n<tr>\n<td>Ashwin plays <strong>both</strong> chess <strong>and</strong> basketball well.</td>\n<td><em>both … and</em>: to emphasise or establish the stronger connection between two things</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Neither, neither of</span></div><div class=\"box-b\">\n<p><em>Neither</em> = <strong>not the one and not the other</strong> of two. <em>Neither</em> and <em>neither of</em> are “used always with <strong>singular</strong> verbs” (the slide, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1528s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 25:28</a>).</p>\n<ul>\n<li><strong>Neither</strong> ring fits me. / <strong>Neither</strong> parent signed the application form.</li>\n<li><strong>Neither of</strong> them was fit for the job. (before object pronouns)</li>\n<li><strong>Neither of</strong> the pens was working. (before plural countable nouns)</li>\n</ul>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Was or were after neither of? (my note)</span></div><div class=\"box-b\">\n<p>The slide prints “Neither of the pens were working”. Many people say <em>were</em> in speech, but the rule on the same slide (“always with singular verbs”) gives <em>was</em>, the safe choice in writing and in exams.</p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Either, either of</span></div><div class=\"box-b\">\n<p><em>Either</em> = <strong>one or the other</strong> of two (it does not matter which). <em>Either</em> and <em>either of</em> are “always used with <strong>singular</strong> verbs” (the slide, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1593s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 26:33</a>).</p>\n<ul>\n<li>I don’t prefer <strong>either</strong> cup. / <strong>Either</strong> bag will be okay, as they both have a sling.</li>\n<li>She doesn’t like apples and she doesn’t like pears <strong>either</strong>. (<em>either</em> as an adverb, after a verb, in a negative context)</li>\n<li><strong>Either of</strong> the boys can go with the team. (before the definite article <em>the</em>)</li>\n<li>I would prefer that <strong>either of</strong> my sisters sing at the ceremony. (before possessives)</li>\n</ul>\n</div></section>\n<p>In the last sentence the verb is <em>sing</em>, not <em>sings</em>. After <em>I would prefer that …</em>, English uses the plain form of the verb, whatever the subject; the lecturer puts this down to “the modality” of the sentence (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1650s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 27:30</a>). (Mood and modality: <a href=\"#/english2/w05/modality-and-mood\">Week 5</a>.)</p>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Either and neither are for two</span></div><div class=\"box-b\">\n<p>The slide says <em>both, either</em> and <em>neither</em> are for <strong>two</strong> people or things. In the talk, the lecturer also uses <em>neither</em> for “none out of many” (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1530s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 25:30</a>). In standard English, for three or more we use <em>none</em> (and <em>any</em>): <em>None of the five pens was working</em> (my example).</p>\n</div></section>\n<h3 id=\"each-and-every\">Each and every</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Each, every</span></div><div class=\"box-b\">\n<p>“<em>Each, each of</em> and <em>every, every single, every other</em> to refer to the <strong>individual</strong> things or persons in a group of two or more. They are always used with <strong>singular</strong> verbs” (the slides, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1692s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 28:12</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1753s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 29:13</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>The slide’s example</th>\n<th>Note on the slide</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>We spent <strong>each</strong> rupee carefully, as we had to save money for the trip.</td>\n<td>before nouns</td>\n</tr>\n<tr>\n<td>We made three muffins, <strong>each</strong> with a different shape.</td>\n<td>as a pronoun</td>\n</tr>\n<tr>\n<td><strong>Each of</strong> their works is scrutinized well.</td>\n<td>before possessives</td>\n</tr>\n<tr>\n<td><strong>Each of</strong> us will carry a torch.</td>\n<td>before object pronouns; <em>each one of us</em> can replace <em>each of us</em></td>\n</tr>\n<tr>\n<td><strong>Every</strong> child deserves good education.</td>\n<td>a singular countable noun</td>\n</tr>\n<tr>\n<td>This is a busy airport. You can see a flight either taking off or landing <strong>every</strong> ten minutes. / The fair happens <strong>every</strong> December.</td>\n<td>to refer to regular intervals of time or number</td>\n</tr>\n</tbody>\n</table></div>\n<p>In the muffin sentence, one word, <em>each</em>, lets us talk about all three muffins <strong>one by one</strong>: a “creative” pronoun use (<a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1710s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 28:30</a>).</p>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Singular or plural verb?</span></div><div class=\"box-b\">\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Quantifier</th>\n<th>How many</th>\n<th>Verb</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>both</td>\n<td>two, together</td>\n<td>plural: <em>Both of them <strong>are</strong> …</em></td>\n</tr>\n<tr>\n<td>either</td>\n<td>one of two</td>\n<td>singular: <em>Either bag <strong>will be</strong> okay.</em></td>\n</tr>\n<tr>\n<td>neither</td>\n<td>not one of two</td>\n<td>singular: <em>Neither ring <strong>fits</strong> me.</em></td>\n</tr>\n<tr>\n<td>each, every</td>\n<td>each member, one by one</td>\n<td>singular: <em>Each of their works <strong>is</strong> …</em>, <em>Every child <strong>deserves</strong> …</em></td>\n</tr>\n</tbody>\n</table></div>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Read closely</span></div><div class=\"box-b\">\n<p>Both lectures end with the same advice: grammar exercises rarely explain meanings, so read closely. Spend an hour reading from any source, not casually, and notice how quantifiers are used and what they add (<a href=\"https://www.youtube.com/watch?v=z-ILfHZhyc8&amp;t=1410s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:30</a>, <a href=\"https://www.youtube.com/watch?v=hAOxHB_bJVQ&amp;t=1830s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 30:30</a>).</p>\n</div></section>\n<h2 id=\"contrast-words\">Contrast words</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>Opposite words such as <em>big/small, tall/short, strong/weak</em> contrast two words. <strong>Contrast words</strong> do something bigger: they join two <strong>ideas</strong> that stand in opposition (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 0:00</a>). Usually one idea is an <strong>expectation</strong> (what we thought would happen) and the other a <strong>result</strong> (what actually happened) (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=150s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:30</a>).</p>\n</div></section>\n<p>The lecture builds everything from one <strong>primary sentence</strong>, two ideas without any contrast word (the slide, <a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=73s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 1:13</a>):</p>\n<blockquote>\n<p>I invited Vaiga to the party. She didn’t come.</p>\n</blockquote>\n<p>The context: it is my birthday; I invited Vaiga; I expected her to come; she did not.</p>\n<h3 id=\"but\">But</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">But</span></div><div class=\"box-b\">\n<p><em>I invited Vaiga to the party <strong>but</strong> she didn’t come.</em> “Result is in opposition to the expectation.” <em><strong>But</strong></em> is the simplest contrast word (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=120s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:00</a>).</p>\n</div></section>\n<h3 id=\"although-and-though\">Although and though</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Although</span></div><div class=\"box-b\">\n<p><em>Although</em> can come at the <strong>beginning</strong> of the sentence or in the <strong>middle</strong> (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=210s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:30</a>):</p>\n<ul>\n<li><em><strong>Although</strong> I invited Vaiga to the party, she didn’t come.</em> (expectation + result)</li>\n<li><em>Vaiga didn’t come to the party <strong>although</strong> I invited her.</em> (result + expectation)</li>\n</ul>\n<p>Both mean the same, but <strong>what comes after <em>although</em> has more emphasis</strong>. In the second sentence the result comes first and the expectation next, which “adds focus to the expectation” (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=300s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:00</a>).</p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Though</span></div><div class=\"box-b\">\n<p><em>Though</em> is the <strong>shortened form</strong> of <em>although</em>. It is <strong>informal</strong>: we use it more in speech than in writing. Like <em>although</em>, it can start the sentence or come in the middle (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=360s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:00</a>):</p>\n<ul>\n<li><em><strong>Though</strong> I invited Vaiga to the party, she didn’t come.</em></li>\n<li><em>Vaiga didn’t come to the party <strong>though</strong> I invited her.</em></li>\n</ul>\n<p>In writing, prefer <em>although</em> (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=420s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 7:00</a>).</p>\n</div></section>\n<h3 id=\"even-though\">Even though</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Even though</span></div><div class=\"box-b\">\n<p><em>Even though</em> is a <strong>stronger form</strong> of <em>although</em>: it <strong>expresses disappointment</strong> (the slide, <a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=482s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 8:02</a>).</p>\n<ul>\n<li><em><strong>Even though</strong> I invited Vaiga to the party, she didn’t come.</em> (the result is in focus)</li>\n<li><em>Vaiga didn’t come to the party <strong>even though</strong> I invited her.</em> (the expectation is in focus: the stronger sentence)</li>\n</ul>\n</div></section>\n<p>Which sentence shows the disappointment more clearly? The second: the expectation (<em>I invited her</em>) follows <em>even though</em>, so the focus is on how the person “has not met my expectation” (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=540s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:00</a>).</p>\n<h3 id=\"however\">However</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">However</span></div><div class=\"box-b\">\n<p><em>However</em> has the <strong>same meaning as <em>but</em></strong>, but it is a <strong>formal</strong> word: use <em>but</em> in speech and <em>however</em> in writing (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=600s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:00</a>, <a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=690s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:30</a>).</p>\n<ul>\n<li><em>I invited Vaiga to the party <strong>but</strong> she didn’t come.</em> (the contraction <em>didn’t</em> is fine)</li>\n<li><em>I invited Vaiga to the party; <strong>however</strong>, she did not come.</em> (formal: no contraction)</li>\n</ul>\n</div></section>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">No contractions in formal writing</span></div><div class=\"box-b\">\n<p>A <strong>contraction</strong> is a short form with an apostrophe: <em>didn’t</em> = <em>did not</em>, <em>isn’t</em> = <em>is not</em>. The lecturer wrote <em>did not</em> in the <em>however</em> sentence on purpose: <em>however</em> is formal, and “it is better to avoid contractions in formal writing” (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=690s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:30</a>).</p>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Punctuation with however</span></div><div class=\"box-b\">\n<p>The slide writes the sentence without punctuation around <em>however</em>. When <em>however</em> joins two complete sentences, put a <strong>semicolon</strong> before it and a <strong>comma</strong> after it: <em>… to the party; however, she did not come.</em> Lecture 11.6 gives the same rule (<a href=\"#/english2/w11/connecting-two-clauses\">below</a>); <a href=\"#/english2/w09\">Week 9</a> covers the semicolon.</p>\n</div></section>\n<h3 id=\"despite-and-in-spite-of\">Despite and in spite of</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Despite, in spite of</span></div><div class=\"box-b\">\n<p>“Both mean the same. You can use them interchangeably” (the slide, <a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=758s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 12:38</a>). The slide rewrites a sentence with <em>even though</em>:</p>\n<ul>\n<li><em>Reva decided to buy an expensive car <strong>even though</strong> her mother objected to it.</em></li>\n<li><em>Reva decided to buy an expensive car <strong>despite</strong> her mother’s objections.</em></li>\n<li><em>Reva decided to buy an expensive car <strong>in spite of</strong> her mother’s objections.</em></li>\n</ul>\n</div></section>\n<p>The difference is the <strong>structure</strong> of what follows (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=870s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 14:30</a>):</p>\n<ul>\n<li>After <em>although, though, even though</em> comes a <strong>clause</strong> that could stand on its own as a sentence: <em>her mother objected to it</em>.</li>\n<li>After <em>despite</em> and <em>in spite of</em> comes a <strong>phrase</strong> (a noun phrase or a verb phrase), which cannot stand on its own: <em>her mother’s objections</em>.</li>\n</ul>\n<p>A <strong>clause</strong> has a subject and a verb (<em>her mother objected</em>); a <strong>phrase</strong> does not have both (<em>her mother’s objections</em>). Words of the same category can still need very different sentence structures (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=930s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 15:30</a>).</p>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Never “despite of”</span></div><div class=\"box-b\">\n<p><em>Despite of</em> “is absolutely wrong” (<a href=\"https://www.youtube.com/watch?v=pLPzXo8xgBA&amp;t=960s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:00</a>). Say <em><strong>despite</strong></em> or <em><strong>in spite of</strong></em>. (The slide spells “inspite of”; it is three words: <em>in spite of</em>.)</p>\n</div></section>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">A clause after despite</span></div><div class=\"box-b\">\n<p>✗ <em>Reva bought the car despite her mother objected.</em> (a clause after <em>despite</em>)\n✓ <em>Reva bought the car despite her mother’s objections.</em> ✓ <em>Reva bought the car even though her mother objected.</em> (My examples, built from the lecture’s.)</p>\n</div></section>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">One “of” only</span></div><div class=\"box-b\">\n<p><em>In spite <strong>of</strong></em> has an <em>of</em>; <em>despite</em> has none, because <em>despite</em> already means “in spite of”. <em>Despite of</em> would say <em>of</em> twice.</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Contrast word (style)</th>\n<th>Where it goes</th>\n<th>What follows</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><em>but</em> (the simplest)</td>\n<td>between the two ideas</td>\n<td>a clause</td>\n</tr>\n<tr>\n<td><em>although</em> (formal, writing)</td>\n<td>beginning or middle</td>\n<td>a clause</td>\n</tr>\n<tr>\n<td><em>though</em> (informal, speech)</td>\n<td>beginning or middle</td>\n<td>a clause</td>\n</tr>\n<tr>\n<td><em>even though</em> (stronger: disappointment)</td>\n<td>beginning or middle</td>\n<td>a clause</td>\n</tr>\n<tr>\n<td><em>however</em> (formal, writing)</td>\n<td>between two sentences</td>\n<td>a clause (after <em>;</em> and <em>,</em>)</td>\n</tr>\n<tr>\n<td><em>despite</em>, <em>in spite of</em> (same meaning)</td>\n<td>before the phrase</td>\n<td>a noun phrase or verb phrase</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"words-and-morphemes\">Words and morphemes</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>Words are the most significant component of a language: they “sustain our ideas”, “translate our ideas” and let us express ourselves (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=90s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 1:30</a>). The building blocks of a language are (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=30s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 0:30</a>):</p>\n<ol>\n<li><strong>Sounds</strong>, studied in <strong>phonology</strong>.</li>\n<li><strong>Words</strong>, studied in <strong>morphology</strong> (the study of how words are built).</li>\n<li><strong>Sentences</strong>, or <strong>utterances</strong>: meaningful strings of words.</li>\n<li><strong>Paragraphs</strong>, and then a whole <strong>text</strong>.</li>\n</ol>\n<p>Meaning is studied in <strong>semantics</strong>; the overall understanding of a text (meaning in context) is <strong>pragmatics</strong> (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=90s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 1:30</a>).</p>\n</div></section>\n<h3 id=\"words-keep-changing\">Words keep changing</h3>\n<p>Words are a <strong>dynamic</strong> class: we keep adding to it (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=120s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:00</a>). After the IT revolution every language added computer words, mostly borrowed from English. A new thing or idea needs a name, and a language either <strong>coins a new word</strong> or <strong>extends the meaning</strong> of an old one (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=240s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:00</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Semantic extension</span></div><div class=\"box-b\">\n<p><strong>Semantic extension</strong> = adding a new meaning to an existing word (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=210s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:30</a>). <em>Download</em> and <em>upload</em> were not new words, but digital technology extended their meaning. A <em>mouse</em> is an animal; in computers it is also a <strong>peripheral</strong> (a device attached to a computer). A <em>window</em> is “a hole in a wall for ventilation”; now it is also a window in software.</p>\n</div></section>\n<h3 id=\"breaking-a-word-into-parts\">Breaking a word into parts</h3>\n<section class=\"box ex\"><div class=\"box-h\"><span class=\"box-k\">Worked example</span><span class=\"box-t\">Nationalization, part by part (the lecture’s example at <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=258s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:18</a>)</span></div><div class=\"box-b\">\n<ol>\n<li>Start with the whole word: <em>nationalization</em> (a noun).</li>\n<li>Remove <em>-ation</em>: <em>nationalize</em> (a verb).</li>\n<li>Remove <em>-ize</em>: <em>national</em> (an adjective).</li>\n<li>Remove <em>-al</em>: <em>nation</em> (a noun).</li>\n<li>Try <em>na</em> + <em>tion</em>: neither part means anything, so we stop. “The more you further break it, meaning is lost” (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=390s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:30</a>).</li>\n</ol>\n<p><strong>Answer:</strong> <em>nationalization</em> = <em>nation</em> + <em>-al</em> + <em>-ize</em> + <em>-ation</em>, four meaningful parts. Each ending changes the word class: noun → adjective → verb → noun.</p>\n</div></section>\n<p>The lecturer’s second chain: <em>response, responsible, responsibility</em> …, and “every time, you find a different meaning” (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=330s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:30</a>).</p>\n<p>Not every string of sounds is a word: words are <strong>meaningful</strong> combinations of sounds (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=390s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:30</a>). And <em>-al, -ize, -tion</em> are not words at all, yet they are essential: attached to a word, they “extend, modify or change the meaning” (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=450s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 7:30</a>). Such units are called <strong>morphemes</strong> (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=510s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 8:30</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Morpheme</span></div><div class=\"box-b\">\n<p>The slide “Words” (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=258s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:18</a>):</p>\n<ul>\n<li>The smallest units of language that have a <strong>meaning</strong> or a <strong>grammatical function</strong> and form words or parts of words are called <strong>morphemes</strong>.</li>\n<li>Morphemes are meaningful units which constitute a word or, as grammatical units, are instrumental in the construction of new words.</li>\n<li>Depending on the way morphemes occur in an utterance, they are grouped into two large groups: <strong>free morphemes</strong> and <strong>bound morphemes</strong>.</li>\n</ul>\n</div></section>\n<p>This is true of every human language, not only English: think of your mother tongue and you will find the same kinds of units (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=810s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:30</a>).</p>\n<h3 id=\"the-classification-of-morphemes\">The classification of morphemes</h3>\n<p>The slide “Classification of Morphemes” (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=667s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:07</a>):</p>\n<ul>\n<li><strong>Morphemes</strong>\n<ul>\n<li><strong>Free morphemes</strong>: lexical morphemes; grammatical morphemes</li>\n<li><strong>Bound morphemes</strong>: bound roots; affixes (prefixes, infixes, suffixes)</li>\n</ul>\n</li>\n</ul>\n<h3 id=\"free-morphemes\">Free morphemes</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Free (independent) morphemes</span></div><div class=\"box-b\">\n<p>“Such morphemes occur alone as words and have a meaning or fulfill a grammatical function; e.g., <em>man, run, and</em>. There are two types” (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=833s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:53</a>):</p>\n<ul>\n<li><strong>Lexical</strong> (referential) morphemes have <strong>semantic content</strong> (meaning) and usually refer to a thing, quality, state or action. They are <strong>nouns, verbs, adjectives and adverbs</strong>: <em>dog, Peter, house, build, stay, happy, intelligent, quickly, always</em>. They form the <strong>open class</strong> of words (the <strong>content words</strong>).</li>\n<li><strong>Functional</strong> (grammatical) morphemes have little or no meaning on their own, but they show <strong>grammatical relationships</strong> in and between sentences. They are <strong>prepositions, conjunctions, articles, demonstratives, auxiliary verbs, pronouns</strong>: <em>with, but, the, this, can, who, me</em>.</li>\n</ul>\n</div></section>\n<p>Some terms: <strong>articles</strong> are <em>a, an, the</em>; <strong>demonstratives</strong> point to something (<em>this, that, these, those</em>); <strong>auxiliary verbs</strong> are helping verbs (<em>is, have, do, can, will</em>); <strong>conjunctions</strong> join (<em>and, if, whether</em>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Open class and closed class</span></div><div class=\"box-b\">\n<ul>\n<li>An <strong>open class</strong> keeps growing. We keep adding nouns, verbs, adjectives and adverbs to English; nobody can count them (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=990s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:30</a>).</li>\n<li>A <strong>closed class</strong> almost never gets new members (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1200s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:00</a>).</li>\n</ul>\n</div></section>\n<p>The lecturer’s test (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1050s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:30</a>): in the last 50 or 100 years, has English added a new <strong>preposition</strong> (<em>in, on, at, under, over, by, with</em>)? A new <strong>article</strong> besides <em>a</em> and <em>the</em>? A new form of the verb <em>be</em> (<em>is, am, are, was, were</em>), or a new <strong>modal</strong> (<em>can, could, may, might, shall, should, will, would</em>)? A new <strong>pronoun</strong>? Practically none. The one change he mentions: the old pronouns <em>thou, thee, thy</em> have given way to <em>you</em> in modern English (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1080s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:00</a>).</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th></th>\n<th>Lexical (content) morphemes</th>\n<th>Functional (grammatical) morphemes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>meaning</td>\n<td>a meaning of their own</td>\n<td>little meaning; they show grammar</td>\n</tr>\n<tr>\n<td>word classes</td>\n<td>nouns, verbs, adjectives, adverbs</td>\n<td>prepositions, conjunctions, articles, demonstratives, auxiliaries, pronouns</td>\n</tr>\n<tr>\n<td>class</td>\n<td>open: keeps growing</td>\n<td>closed: rarely changes</td>\n</tr>\n<tr>\n<td>examples</td>\n<td>dog, run, happy, quickly</td>\n<td>with, but, the, this, can, me</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"bound-morphemes\">Bound morphemes</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Bound (dependent) morphemes</span></div><div class=\"box-b\">\n<p>“Such morphemes never occur alone as words but as parts of words; they must be attached to another morpheme (usually a free morpheme) in order to have a distinct meaning” (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1238s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:38</a>). Examples: <em>-er</em> in <em>worker</em>, <em>-er</em> in <em>taller</em>, <em>-s</em> in <em>walks</em>, <em>-ed</em> in <em>passed</em>, <em>re-</em> in <em>reappear</em>, <em>un-</em> in <em>unhappy, undo</em>, <em>-ness</em> in <em>readiness</em>, <em>-able</em> in <em>adjustable</em>, <em>-ceive</em> in <em>conceive, receive</em>, <em>-tain</em> in <em>contain, obtain</em>.</p>\n</div></section>\n<p>The same slide gives two types of bound morphemes:</p>\n<ul>\n<li><strong>Bound roots</strong> have a lexical meaning, but only when attached to other morphemes: <em>-ceive</em> in <em>receive, conceive</em>; <em>-tain</em> in <em>retain, contain</em>; <em>plac-</em> in <em>implacable, placate</em>; <em>cran-</em> in <em>cranberry</em>. Bound roots can take prefixes or suffixes.</li>\n<li><strong>Affixes</strong> are attached to words and change their meaning or function: <em>-ment</em> in <em>development</em>, <em>en-</em> in <em>enlarge</em>, <em>'s</em> in <em>John’s</em>, <em>-s</em> in <em>claps</em>, <em>-ing</em> in <em>studying</em>.</li>\n</ul>\n<p>A <strong>root</strong> is the core of a word, the part that carries its main meaning. Some roots stand alone (<em>nation</em>); bound roots do not (<em>-ceive</em>). The lecturer’s examples of affixes: <em>play</em> + <em>-er</em> = <em>player</em>; <em>un-</em> + <em>happy</em> = <em>unhappy</em> (the opposite meaning); <em>-able</em> in <em>adjustable, applicable</em> (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1260s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:00</a>).</p>\n<h3 id=\"affixes-by-position-prefix-infix-suffix\">Affixes by position: prefix, infix, suffix</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Prefix, infix, suffix</span></div><div class=\"box-b\">\n<p><strong>Affixation</strong> means fixing (attaching) an affix to an existing word (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1350s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:30</a>). By their position, the slide “Types of Affixes” (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1382s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:02</a>) gives:</p>\n<ul>\n<li><strong>Prefixes</strong> are added to the <strong>beginning</strong> of the word: <em>un-</em> in <em>unnoticed</em>, <em>a-</em> in <em>amoral</em>, <em>sub-</em> in <em>subway</em>.</li>\n<li><strong>Infixes</strong> are inserted <strong>within</strong> the word. “There are no infixes in the English language.” (Malay has them, the lecturer says, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=630s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:30</a>.)</li>\n<li><strong>Suffixes</strong> are attached to the <strong>end</strong> of the word: <em>-able</em> in <em>noticeable</em>, <em>-less</em> in <em>careless</em>, <em>-s</em> in <em>seeks</em>, <em>-en</em> in <em>shorten</em>.</li>\n</ul>\n</div></section>\n<h3 id=\"affixes-by-function-derivational-and-inflectional\">Affixes by function: derivational and inflectional</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Derivational affixes</span></div><div class=\"box-b\">\n<p>“Derivational affixes are morphemes that create (or derive) <strong>new words</strong>, usually by either changing the <strong>meaning</strong> and/or the <strong>part of speech</strong> (i.e., the syntactic category), or both, of the words they are attached to.” In English they can be prefixes or suffixes: <em>un-</em> + <em>happy</em> (adj.) = <em>unhappy</em> (adj.); <em>re-</em> + <em>classify</em> (v.) = <em>reclassify</em> (v.); <em>by-</em> + <em>product</em> (n.) = <em>by-product</em> (n.) (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1401s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:21</a>).</p>\n</div></section>\n<p>A <strong>part of speech</strong> (or word class) is the group a word belongs to: noun, verb, adjective, adverb, and so on. Derivation is “very prolific”: from one root we derive many words, often of different classes (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1470s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:30</a>). New ones keep coming: <em>befriend</em>, and from social media, <em>defriend</em> (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1560s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 26:00</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Inflectional affixes</span></div><div class=\"box-b\">\n<p>“Inflectional affixes … serve a purely <strong>grammatical</strong> function”, such as giving extra information about the word’s existing meaning (number, person, gender, case) or showing relations between words (possession, comparison) (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1837s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 30:37</a>). They make a <strong>variant</strong> of the same word, and the word class <strong>does not change</strong>: <em>car → cars</em> is still a noun; <em>fast → faster → fastest</em> is still an adjective (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1680s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 28:00</a>).</p>\n</div></section>\n<p>“In English, there are only <strong>eight</strong> inflections” (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1837s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 30:37</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Inflection</th>\n<th>It marks</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>-(e)s</td>\n<td>third person singular, present tense (verbs)</td>\n<td>speaks, teaches</td>\n</tr>\n<tr>\n<td>2</td>\n<td>-(e)s</td>\n<td>regular plural (nouns)</td>\n<td>books, oranges</td>\n</tr>\n<tr>\n<td>3</td>\n<td>'s</td>\n<td>possessive</td>\n<td>John’s house</td>\n</tr>\n<tr>\n<td>4</td>\n<td>-(e)d</td>\n<td>regular past tense</td>\n<td>helped, repeated</td>\n</tr>\n<tr>\n<td>5</td>\n<td>-en</td>\n<td>past participle</td>\n<td>spoken, eaten</td>\n</tr>\n<tr>\n<td>6</td>\n<td>-ing</td>\n<td>present participle</td>\n<td>eating, studying</td>\n</tr>\n<tr>\n<td>7</td>\n<td>-er</td>\n<td>comparative</td>\n<td>faster, happier</td>\n</tr>\n<tr>\n<td>8</td>\n<td>-est</td>\n<td>superlative</td>\n<td>fastest, happiest</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Third person singular</strong> means the subject is <em>he, she, it</em> or one person or thing: <em>she speaks, the bus goes</em>. Irregular verbs show the same grammar in other ways: <em>go → went</em>, <em>write → wrote</em> (past tense); <em>go → gone</em>, <em>write → written</em> (past participle) (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1920s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 32:00</a>).</p>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Derivation or inflection? Ask about the word</span></div><div class=\"box-b\">\n<ol>\n<li>Does the word class change (<em>kind</em> → <em>kindness</em>: adjective → noun)? Then it is <strong>derivation</strong>.</li>\n<li>Does the class stay but the meaning change (<em>happy</em> → <em>unhappy</em>)? Still <strong>derivation</strong>: a new word.</li>\n<li>Does only a grammatical feature change (number, tense, person, comparison: <em>car</em> → <em>cars</em>, <em>go</em> → <em>goes</em>, <em>fast</em> → <em>fastest</em>)? Then it is <strong>inflection</strong>.</li>\n</ol>\n</div></section>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Two different -ers, two different -s’s</span></div><div class=\"box-b\">\n<p><em>-er</em> in <em>worker</em> is <strong>derivational</strong>: the verb <em>work</em> becomes the noun <em>worker</em>. <em>-er</em> in <em>taller</em> is <strong>inflectional</strong>: the comparative of the adjective <em>tall</em>, still an adjective. The bound-morpheme slide lists both (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=1238s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:38</a>). In the same way, <em>-s</em> in <em>walks</em> (a verb, third person) and <em>-s</em> in <em>books</em> (a noun, plural) are two different inflections.</p>\n</div></section>\n<h3 id=\"derivational-affixes-by-the-word-they-make\">Derivational affixes, by the word they make</h3>\n<p>The slides list suffixes by the word class they produce (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2065s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 34:25</a>, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2192s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 36:32</a>, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2266s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 37:46</a>).</p>\n<p><strong>Noun-forming suffixes</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>From</th>\n<th>+ suffix</th>\n<th>= noun</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>assist (v)</td>\n<td>-ance</td>\n<td>assistance</td>\n</tr>\n<tr>\n<td>assist (v)</td>\n<td>-ant</td>\n<td>assistant</td>\n</tr>\n<tr>\n<td>confide (v)</td>\n<td>-ence</td>\n<td>confidence</td>\n</tr>\n<tr>\n<td>permute (v)</td>\n<td>-ation</td>\n<td>permutation</td>\n</tr>\n<tr>\n<td>compete (v)</td>\n<td>-ition</td>\n<td>competition</td>\n</tr>\n<tr>\n<td>young (adj)</td>\n<td>-ster</td>\n<td>youngster</td>\n</tr>\n<tr>\n<td>industrial (adj)</td>\n<td>-ist</td>\n<td>industrialist</td>\n</tr>\n<tr>\n<td>crude (adj)</td>\n<td>-ity</td>\n<td>crudity</td>\n</tr>\n<tr>\n<td>dry (adj)</td>\n<td>-ness</td>\n<td>dryness</td>\n</tr>\n<tr>\n<td>free (adj)</td>\n<td>-dom</td>\n<td>freedom</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Confident is an adjective</span></div><div class=\"box-b\">\n<p>The slide also lists <em>confide</em> + <em>-ent</em> = <em>confident</em> among the noun-forming suffixes. <em>Confident</em> is an <strong>adjective</strong> (<em>a confident speaker</em>). The noun spelt almost the same way is <em>confidant</em>: a person you confide in, that is, tell your secrets to.</p>\n</div></section>\n<p><strong>Adjective-forming suffixes</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>From</th>\n<th>+ suffix</th>\n<th>= adjective</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>eat (v)</td>\n<td>-able</td>\n<td>eatable</td>\n</tr>\n<tr>\n<td>reduce (v)</td>\n<td>-ible</td>\n<td>reducible</td>\n</tr>\n<tr>\n<td>differ (v)</td>\n<td>-ent</td>\n<td>different</td>\n</tr>\n<tr>\n<td>signify (v)</td>\n<td>-ant</td>\n<td>significant</td>\n</tr>\n<tr>\n<td>act (v)</td>\n<td>-ive</td>\n<td>active</td>\n</tr>\n<tr>\n<td>fashion (n)</td>\n<td>-able</td>\n<td>fashionable</td>\n</tr>\n<tr>\n<td>response (n)</td>\n<td>-ible</td>\n<td>responsible</td>\n</tr>\n<tr>\n<td>magic (n)</td>\n<td>-al</td>\n<td>magical</td>\n</tr>\n<tr>\n<td>planet (n)</td>\n<td>-ary</td>\n<td>planetary</td>\n</tr>\n<tr>\n<td>affection (n)</td>\n<td>-ate</td>\n<td>affectionate</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Verb-forming affixes</strong></p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>From</th>\n<th>+ suffix</th>\n<th>= verb</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>black (adj)</td>\n<td>-en</td>\n<td>blacken</td>\n</tr>\n<tr>\n<td>solid (adj)</td>\n<td>-ify</td>\n<td>solidify</td>\n</tr>\n<tr>\n<td>beauty (n)</td>\n<td>-ify</td>\n<td>beautify</td>\n</tr>\n<tr>\n<td>computer (n)</td>\n<td>-ize</td>\n<td>computerize</td>\n</tr>\n<tr>\n<td>length (n)</td>\n<td>-en</td>\n<td>lengthen</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Prefixes that change the word class</strong> (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2348s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 39:08</a>): <em>a-sleep</em> → <em>asleep</em>, <em>be-friend</em> → <em>befriend</em>, <em>em-power</em> → <em>empower</em>, <em>en-danger</em> → <em>endanger</em>, <em>be-little</em> → <em>belittle</em>, <em>en-large</em> → <em>enlarge</em>.</p>\n<p>The slide labels them “prefix + noun → verb”. That fits <em>befriend, empower, endanger</em>. In <em>belittle</em> and <em>enlarge</em> the base is an adjective (<em>little, large</em>); and <em>asleep</em> is an adjective, not a verb (<em>The baby is asleep</em>).</p>\n<p><strong>Affixes that do not change the word class</strong> (the slide, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2384s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 39:44</a>): the noun stays a noun; the suffix adds a shade of meaning.</p>\n<ul>\n<li><em>-ette</em>: cigar → cigarette, usher → usherette, flannel → flannelette</li>\n<li><em>-ful</em>: hand → handful; <em>-hood</em>: boy → boyhood</li>\n<li><em>-ian</em>: mathematics → mathematician, music → musician</li>\n<li><em>-ie, -y</em>: dog → doggie, pig → piggy</li>\n<li><em>-ism</em>: hero → heroism</li>\n<li><em>-ary</em>: function → functionary; <em>-ate</em>: director → directorate</li>\n<li><em>-ee</em>: boot → bootee; <em>-eer</em>: mountain → mountaineer; <em>-er</em>: philosophy → philosopher</li>\n<li><em>-ery, -ry</em>: fish → fishery, cook → cookery, snob → snobbery, rival → rivalry</li>\n</ul>\n<p>“The world of words is beautiful, dynamic, and very fascinating.” The lecturer’s suggestion: keep breaking words into their parts and check whether you see a prefix or a suffix, an inflection or a derivation (<a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2070s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 34:30</a>, <a href=\"https://www.youtube.com/watch?v=KGGeRd7Y-98&amp;t=2400s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 40:00</a>).</p>\n<h2 id=\"word-formation-processes\">Word-formation processes</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>Nobody can count the words of a language: old words go out of fashion and new ones arrive, many through social media (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=60s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 1:00</a>). Sometimes a familiar word is changed: a part is dropped, something is added, or it gets a new meaning. Every language makes new words in a few common, universal ways. The lecturer suggests comparing them with your own mother tongue: human languages share “underlying principles” (Chomsky’s term) (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=210s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:30</a>).</p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Word-formation process</span></div><div class=\"box-b\">\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=157s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:37</a>): “Word formation process refers to all processes connected with creating/changing/modifying the form of the word by making certain changes, addition, deletion, and contracting morphemes. In its wider sense word formation denotes the processes of creation of new <strong>lexical units</strong>.” (A lexical unit is a word, or a word-like item, with its own meaning.)</p>\n</div></section>\n<p>The slide asks three questions. How are new words formed in the language? How does the process combine morphemes by rules? How does understanding the process help us understand the language? The combinations are not random: they are <strong>rule-governed</strong>, and the patterns are <strong>language-specific</strong>, fixed within each language (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=300s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:00</a>).</p>\n<h3 id=\"clipping\">Clipping</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Clipping</span></div><div class=\"box-b\">\n<p>“Clipping is the word formation process which consists in the reduction of a word to one of its parts (Marchand: 1969). Clippings are, also, known as ‘shortenings’” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=361s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:01</a>). The shorter word keeps the meaning of the long one.</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>What is cut off</th>\n<th>The slide’s examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>back clipping</td>\n<td>the end</td>\n<td>ad (advertisement), cable (cablegram), doc (doctor), exam (examination), gas (gasoline), math (mathematics), memo (memorandum), gym (gymnastics, gymnasium), fax (facsimile)</td>\n</tr>\n<tr>\n<td>fore-clipping</td>\n<td>the beginning</td>\n<td>phone (telephone), varsity (university), chute (parachute), gator (alligator), pike (turnpike)</td>\n</tr>\n<tr>\n<td>middle clipping</td>\n<td>the beginning and the end; the middle stays</td>\n<td>flu (influenza), tec (detective), jams (pyjamas), shrink (head-shrinker)</td>\n</tr>\n<tr>\n<td>complex clipping</td>\n<td>parts of a compound</td>\n<td>cablegram (cable telegram), op art (optical art), org-man (organization man), linocut (linoleum cut)</td>\n</tr>\n</tbody>\n</table></div>\n<p>Sometimes <strong>both halves</strong> of a compound are clipped: <em>navicert</em> (navigation certificate) and <em>advertorial</em> (advertisement + editorial).</p>\n<section class=\"box ex\"><div class=\"box-h\"><span class=\"box-k\">Worked example</span><span class=\"box-t\">What an advertorial is (the lecture’s example at <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=570s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:30</a>)</span></div><div class=\"box-b\">\n<ol>\n<li>Take <em>advertisement</em> and keep its beginning: <em>advert-</em>.</li>\n<li>Take <em>editorial</em> and keep its end: <em>-orial</em>.</li>\n<li>Join the two: <em>advertorial</em>.</li>\n<li>The meanings join too. An <strong>advertorial</strong> is a paid advertisement made to look like a news item. At its end, “in the smallest font possible”, it says <em>advertorial</em>, so that readers take it for news (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=600s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:00</a>).</li>\n</ol>\n<p><strong>Answer:</strong> <em>advertorial</em> = <em>advert(isement)</em> + <em>(edit)orial</em>: an advertisement dressed as news.</p>\n</div></section>\n<h3 id=\"acronymy\">Acronymy</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Acronyms and initialisms</span></div><div class=\"box-b\">\n<p>“Acronyms and initialisms are abbreviations that are formed using the letters of words or word parts in a phrase or name” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=664s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:04</a>). The abbreviation is then used as an independent word.</p>\n</div></section>\n<ul>\n<li><strong>Laser</strong>: light amplification by the stimulated emission of radiation</li>\n<li><strong>NATO</strong>: North Atlantic Treaty Organisation</li>\n<li><strong>Scuba</strong>: self-contained underwater breathing apparatus</li>\n<li><strong>ISBT</strong>: Inter State Bus Terminus</li>\n<li><strong>Noida</strong>, the city near Delhi: New Okhla Industrial Development Authority. Many young people use the name without knowing what it stands for (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=690s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:30</a>).</li>\n</ul>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Acronym or initialism? (my note)</span></div><div class=\"box-b\">\n<p>Say it aloud. If we read it as <strong>one word</strong> (<em>NATO, laser, scuba, Noida</em>), it is an <strong>acronym</strong>. If we read it <strong>letter by letter</strong> (<em>I-S-B-T</em>), it is an <strong>initialism</strong>.</p>\n</div></section>\n<h3 id=\"blending\">Blending</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Blending</span></div><div class=\"box-b\">\n<p>“A blend is a word formed from parts of two other words. These parts are sometimes, but not always, morphemes” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=830s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:50</a>). Most blends are made in one of three ways:</p>\n<ol>\n<li>The <strong>beginning</strong> of one word + the <strong>end</strong> of the other: <em><strong>brunch</strong></em> = <em>br(eakfast)</em> + <em>(l)unch</em>.</li>\n<li>The <strong>beginnings</strong> of two words: <em><strong>cyborg</strong></em> = <em>cyb(ernetic)</em> + <em>org(anism)</em>.</li>\n<li>One <strong>complete</strong> word + <strong>part</strong> of another: <em><strong>guesstimate</strong></em> = <em>guess</em> + <em>(es)timate</em>.</li>\n</ol>\n</div></section>\n<h3 id=\"back-formation\">Back-formation</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Back-formation</span></div><div class=\"box-b\">\n<p>“Back-formation refers to the process of creating a new word by removing actual or supposed affixes. Back-formations are shortened words created from longer words, thus back-formations may be viewed as a sub-type of clipping” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=925s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 15:25</a>).</p>\n</div></section>\n<ul>\n<li>The noun <em>resurrection</em> was borrowed from Latin; “hundreds of years later” the verb <em><strong>resurrect</strong></em> was formed from it by removing the suffix <em>-ion</em>.</li>\n<li><em>Postpone</em> → <em><strong>prepone</strong></em>, the slide’s second example: from <em>postpone</em> (move to a later time), speakers made <em>prepone</em> (move to an earlier time), with <em>pre-</em> (before) in place of <em>post-</em> (after). “Now we use it, it is in vogue” (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=930s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 15:30</a>).</li>\n</ul>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Prepone (my note)</span></div><div class=\"box-b\">\n<p>Dictionaries mark <em>prepone</em> as Indian English. With speakers from other countries, <em>bring forward</em> is safer: <em>The meeting was brought forward to Monday.</em></p>\n</div></section>\n<h3 id=\"borrowing\">Borrowing</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Borrowing and loanwords</span></div><div class=\"box-b\">\n<p>“Borrowing is just taking a word from another language. The borrowed words are called loan words. A loanword (or loan word) is a word directly taken into one language from another with little or no translation. Loanwords can also be called ‘borrowings’” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=989s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:29</a>).</p>\n</div></section>\n<p>Borrowing goes <strong>both ways</strong> (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1080s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:00</a>):</p>\n<ul>\n<li><strong>From English into Indian languages</strong>: <em>road, school, rail</em>, and food words the British brought, such as <em>cake</em> and <em>pastry</em>. It is rare to find an Indian-language word for <em>cake</em>, yet we use the word every day (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1020s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:00</a>).</li>\n<li><strong>From Hindi into English</strong>: <em>loot</em> (to plunder), now in the Oxford dictionary; <em>raita, saree</em>; <em>dharna</em> (a political protest by sitting); <em>lathi</em> and <em>lathi charge</em> (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1080s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:00</a>).</li>\n<li>English has taken many words from <strong>Latin, French and Greek</strong>; the botanical names of plants and trees are Latin (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1140s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:00</a>).</li>\n</ul>\n<p>The slide’s list:</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>From</th>\n<th>The slide’s examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>German</td>\n<td>biology, boxer, ozone</td>\n</tr>\n<tr>\n<td>Turkish</td>\n<td>jacket, yoghurt, kiosk</td>\n</tr>\n<tr>\n<td>Czech</td>\n<td>pistol, robot</td>\n</tr>\n<tr>\n<td>Hindi</td>\n<td>dharna, loot, jungle</td>\n</tr>\n</tbody>\n</table></div>\n<p>We borrow a word together with the thing or idea: “You borrow a dress, you borrow a food item, you borrow cultural practice”, and after a while the word feels like our own (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1230s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:30</a>).</p>\n<h3 id=\"coinage\">Coinage</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Coinage</span></div><div class=\"box-b\">\n<p>“Coinage is the invention of totally new words. The typical process of coinage usually involves the extension of a product name from a specific reference to a more general one” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1276s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:16</a>).</p>\n</div></section>\n<p><em>Kleenex, Xerox</em> and <em>Kodak</em> “started as names of specific products, but now they are used as the generic names for different brands of these types of products”. <em>Xerox</em>, the company that made the photocopying machine, is now even a verb: <em>xerox these pages</em> (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1290s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:30</a>).</p>\n<h3 id=\"compounding\">Compounding</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Compounding</span></div><div class=\"box-b\">\n<p>“A compound is a <strong>lexeme</strong> (a word) that consists of more than one lexeme” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1334s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:14</a>). Two words are put together to make a third word for a new idea (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1320s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:00</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Pattern</th>\n<th>The slide’s examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>noun + noun</td>\n<td>lipstick, teapot</td>\n</tr>\n<tr>\n<td>adjective + noun</td>\n<td>fast food, soft drink</td>\n</tr>\n<tr>\n<td>verb + noun</td>\n<td>breakfast (<em>break</em> + <em>fast</em>)</td>\n</tr>\n<tr>\n<td>noun + verb</td>\n<td>sunshine, babysit, sky-dive</td>\n</tr>\n<tr>\n<td>noun + adjective</td>\n<td>capital-intensive, waterproof</td>\n</tr>\n<tr>\n<td>adjective + adjective</td>\n<td>deaf-mute, bitter-sweet</td>\n</tr>\n</tbody>\n</table></div>\n<p>(The slide puts <em>sky-dive</em> under verb + noun; <em>sky</em> is a noun and <em>dive</em> a verb, so it belongs with noun + verb.)</p>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">A compound has its own meaning</span></div><div class=\"box-b\">\n<p>The meaning of a compound is not always the sum of its parts (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1350s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:30</a>). In <em>lipstick</em>, “a stick has nothing to do with lip”. <em>Mustard oil</em> is oil made <strong>from</strong> mustard, but <em>baby oil</em> is not oil made from babies: it is oil <strong>for</strong> babies, for massaging them. Same pattern, very different meanings.</p>\n</div></section>\n<h3 id=\"inflection-and-derivation\">Inflection and derivation</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Inflection</span></div><div class=\"box-b\">\n<p>“In linguistics, inflection or inflexion is the modification of a word to express different grammatical categories such as tense, grammatical mood, grammatical voice, aspect, person, number, gender and case.” The English word <em>cars</em> is a noun, inflected for <strong>number</strong>: the plural <em>-s</em> is an inflectional suffix (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1446s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:06</a>).</p>\n</div></section>\n<p>The lecturer’s examples (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1440s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:00</a>): <em>go, goes, going, went, gone</em> are all forms of one verb (simple, third person singular, progressive, past, past participle); <em>baby → babies</em>; <em>fast → faster → fastest</em>. The form changes to meet a grammatical need; the word stays the same word (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1470s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:30</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Derivation</span></div><div class=\"box-b\">\n<p>“Derivation is used to form new words with the help of affixation process” (the slide, <a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1556s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 25:56</a>).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Change</th>\n<th>The slide’s example</th>\n<th>More from the talk</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>adjective → noun</td>\n<td><em>-ness</em>: kind → kindness</td>\n<td></td>\n</tr>\n<tr>\n<td>adjective → verb</td>\n<td><em>-ize</em>: modern → modernize</td>\n<td>simple → simplify</td>\n</tr>\n<tr>\n<td>noun → adjective</td>\n<td><em>-al</em>: recreation → recreational</td>\n<td>nation → national</td>\n</tr>\n<tr>\n<td>noun → verb</td>\n<td><em>-fy</em>: glory → glorify</td>\n<td>beauty → beautify; capital → capitalize</td>\n</tr>\n<tr>\n<td>verb → adjective</td>\n<td><em>-able</em>: drink → drinkable</td>\n<td>like → likable</td>\n</tr>\n<tr>\n<td>verb → noun</td>\n<td><em>-ance</em>: deliver → deliverance</td>\n<td>deliver → delivery</td>\n</tr>\n</tbody>\n</table></div>\n<p>Prefixes derive new words too: <em>power → empower, large → enlarge, friend → befriend</em> (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1710s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 28:30</a>).</p>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">Read more</span></div><div class=\"box-b\">\n<p>The slide “For further understanding” (<a href=\"https://www.youtube.com/watch?v=oLZoS0mwhW8&amp;t=1745s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 29:05</a>) lists: Haspelmath, <em>Morphology</em> (2003); Plag, <em>Word-Formation in English</em> (2003); Katamba, <em>English Words</em> (2005); Bloomfield, <em>Language</em> (1962).</p>\n</div></section>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Process</th>\n<th>What happens</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>clipping</td>\n<td>a long word is cut short</td>\n<td>examination → exam</td>\n</tr>\n<tr>\n<td>acronymy</td>\n<td>first letters become a word</td>\n<td>NATO</td>\n</tr>\n<tr>\n<td>blending</td>\n<td>parts of two words are mixed</td>\n<td>breakfast + lunch → brunch</td>\n</tr>\n<tr>\n<td>back-formation</td>\n<td>a (supposed) affix is removed</td>\n<td>resurrection → resurrect</td>\n</tr>\n<tr>\n<td>borrowing</td>\n<td>a word is taken from another language</td>\n<td>loot (from Hindi)</td>\n</tr>\n<tr>\n<td>coinage</td>\n<td>a new word, often a product name</td>\n<td>xerox</td>\n</tr>\n<tr>\n<td>compounding</td>\n<td>two words join</td>\n<td>lip + stick → lipstick</td>\n</tr>\n<tr>\n<td>inflection</td>\n<td>a grammatical form of the same word</td>\n<td>go → goes</td>\n</tr>\n<tr>\n<td>derivation</td>\n<td>an affix makes a new word</td>\n<td>kind → kindness</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"connecting-ideas-within-and-between-sentences\">Connecting ideas within and between sentences</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>The units of language are sounds, then words, then sentences. In communication, what matters most is <strong>discourse</strong>: connected speech or writing in a context. One of the main goals of effective communication is to build a discourse and conclude it “in a convincing way” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=180s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:00</a>). For that we need to know more than sentences: what to say and, more importantly, <strong>what not to say</strong>, and how to look effortless, which “takes a lot of efforts to prepare” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=240s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:00</a>). Small connecting words and phrases do much of this work. (Week 1 introduced <a href=\"#/english2/w01/discourse-markers\">discourse markers</a>.)</p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Connecting ideas</span></div><div class=\"box-b\">\n<p>An <strong>idea</strong> here means a point (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=300s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:00</a>). Some terms connect points <strong>within</strong> one sentence (<strong>intra-sentential</strong>); others connect a sentence with the sentence or sentences <strong>before</strong> it. Most of these terms are <strong>adverbs</strong> and <strong>prepositional phrases</strong>, which are mostly adverbial in nature; their larger function is to <strong>mark the discourse</strong> (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=120s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 2:00</a>).</p>\n</div></section>\n<h3 id=\"between-sentences-adverbs-and-prepositional-phrases\">Between sentences: adverbs and prepositional phrases</h3>\n<p>The slide “Use of Adverbs and Prepositional Phrases” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=318s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:18</a>): “To connect ideas between one sentence and a previous sentence or sentences”.</p>\n<ul>\n<li><em>There was no AC in the building. <strong>As a result</strong>, the workers had to be sent home.</em> <em>As a result</em> makes the first sentence a <strong>precondition</strong>, an existing condition, for what the second sentence says (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=420s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 7:00</a>).</li>\n<li><em>We could go for a movie this Diwali. <strong>Alternatively</strong>, we could just stay at home and enjoy the sweets.</em> The adverb <em>alternatively</em> presents the second idea as an <strong>option</strong> to the first (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=480s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 8:00</a>).</li>\n</ul>\n<p>Used well, such markers have “a greasing effect”: they make things smoother, make writing readable, and keep the audience from losing the point (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=570s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:30</a>).</p>\n<h3 id=\"within-a-sentence-conjunctions\">Within a sentence: conjunctions</h3>\n<p>The slide “Conjunctions and Prepositions” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=600s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:00</a>): “To connect ideas within a single sentence”.</p>\n<ul>\n<li><em><strong>While</strong> I was waiting, I had a cup of coffee.</em> Without <em>while</em>, “I was waiting. I had a cup of coffee” sounds monotonous, a “crude” or “raw” presentation. <em>While</em> joins the two ideas and even gives a reason: the coffee helped to pass the time (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=630s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:30</a>).</li>\n<li><em>I will be wearing a sea-blue shawl <strong>so that</strong> you can see me easily.</em> <em>So that</em> shows that one thing depends on the other: I wear the shawl <strong>for a purpose</strong>, so that you can identify me (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=690s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:30</a>).</li>\n</ul>\n<p>A <strong>conjunction</strong> is a joining word: <em>and, but, or, so, while, because, although</em>.</p>\n<h3 id=\"connecting-two-clauses\">Connecting two clauses</h3>\n<p>The slide “And/ But/ Or/ So/ Semi-Colon(;)/ Colon (:)/ Hyphen (-)” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=818s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:38</a>): these “connect ideas between sentences and … two clauses in the same sentence”.</p>\n<ul>\n<li><em>The building was extremely well constructed <strong>and, consequently,</strong> difficult to demolish.</em> Two markers work together, <em>and</em> plus <em>consequently</em>. After them, <em>difficult to demolish</em> is not a full sentence; it means “it was difficult to demolish” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=900s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 15:00</a>).</li>\n<li><em>You could fly via Singapore</em>*; however,** this isn’t the only way.* The semicolon keeps the two sentences within one, and “after using <em>however</em>, we always use a comma before introducing a new clause” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=960s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:00</a>).</li>\n</ul>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">However between two clauses</span></div><div class=\"box-b\">\n<p><strong>semicolon</strong> + <em><strong>however</strong></em> + <strong>comma</strong>: <em>You could fly via Singapore; however, this isn’t the only way.</em> End the second clause with a full stop (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1080s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:00</a>). (More on the semicolon in <a href=\"#/english2/w09\">Week 9</a>.)</p>\n</div></section>\n<p>The lecturer’s picture: from New Delhi to Los Angeles you could fly west via Europe and across the Atlantic, or east via Singapore, over Tokyo and the Pacific (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=990s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:30</a>). <em>However</em> tells the listener that Singapore is one route among several.</p>\n<h3 id=\"connectors-by-function\">Connectors by function</h3>\n<p>The slides “Examples of Adverbs that Connect Ideas” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1115s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:35</a>, <a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1213s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:13</a>, <a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1297s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:37</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Function</th>\n<th>Between sentences</th>\n<th>Within sentences</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. comparing, contrasting, concession</td>\n<td>however, nevertheless, on the other hand, on the contrary, though, alternatively, instead, after all, in any case, in contrast, by contrast, otherwise, even so</td>\n<td>although, though, even though, while, yet, whereas</td>\n</tr>\n<tr>\n<td>2. causes, reasons, purposes, results</td>\n<td>therefore, consequently, hence, as a consequence, in consequence (formal), thus, as a result, so</td>\n<td>because, since, as, so, in order to, so that</td>\n</tr>\n<tr>\n<td>3. adding ideas</td>\n<td>in addition, furthermore, too, as well, likewise, similarly, moreover, what’s more, also</td>\n<td>(not on the slide)</td>\n</tr>\n<tr>\n<td>4. time: one event at the same time as another</td>\n<td>meanwhile, at the same time, at that time</td>\n<td>while, as, when, whenever</td>\n</tr>\n<tr>\n<td>5. time: one event before another</td>\n<td>soon, then, afterwards, after that, before that, subsequently</td>\n<td>after, before, as soon as, since</td>\n</tr>\n</tbody>\n</table></div>\n<p>A <strong>concession</strong> admits a fact that seems to work against your main point: <em>Although it was raining, we went out</em> (my example). These markers are useful in every domain: professional or personal, writing or speaking (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1140s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:00</a>). The lecturer’s advice: make a list of them and write a couple of sentences of your own with each one (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1260s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:00</a>).</p>\n<h3 id=\"even-though-even-so-however\">Even though, even so, however</h3>\n<p>The slides (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1323s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:03</a>, <a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1420s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:40</a>, <a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1482s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:42</a>):</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Even though</span></div><div class=\"box-b\">\n<p>“<em>Even though</em> is a <strong>conjunction</strong> used to say that a fact does not make the rest of the sentence untrue. It connects ideas <strong>within</strong> a sentence.”</p>\n<p><em>Even though trade unions are no longer as powerful as they used to be, their political influence should not be underestimated.</em></p>\n</div></section>\n<p>The fact (unions are weaker now) is true, and it does not cancel the main point after the comma, which is what draws attention (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=1350s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:30</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Even so</span></div><div class=\"box-b\">\n<p>“<em>Even so</em> is a <strong>prepositional phrase</strong> used to introduce a fact that is <strong>surprising</strong> in light of what was just said. It connects ideas <strong>between</strong> sentences.”</p>\n<p><em>Much of the power of trade unions has been lost. Even so, their political influence should not be underestimated.</em></p>\n</div></section>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">However = no matter how</span></div><div class=\"box-b\">\n<p>“<em>However</em> is used to connect ideas between sentences, but also <strong>within</strong> a sentence when it is followed by an <strong>adjective</strong> or an <strong>adverb</strong> such as <em>much</em> or <em>many</em>.” Then it means “<strong>no matter how</strong>”:</p>\n<ul>\n<li><em>We just don’t have the money to do the work, <strong>however necessary</strong> you think it is.</em> (The work may be very necessary; we still have no money.)</li>\n<li><em><strong>However</strong> he held the mirror, he could not see the back of his neck.</em> (In whatever way he held it.)</li>\n</ul>\n</div></section>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Even though or even so?</span></div><div class=\"box-b\">\n<p>The two carry the same message with different grammar:</p>\n<ul>\n<li><em><strong>Even though</strong></em> + a clause, a comma, then the main clause: <strong>one</strong> sentence.</li>\n<li>A sentence. <em><strong>Even so</strong></em>, + a sentence: <strong>two</strong> sentences.</li>\n</ul>\n<p>✗ <em>Much of the power has been lost, even so their influence remains.</em> (two sentences joined only by a comma) ✓ <em>Much of the power has been lost. Even so, their influence remains.</em> (My example.)</p>\n</div></section>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">The lecture’s exercise</span></div><div class=\"box-b\">\n<p>Take a 5-minute audio sample from anywhere: television, a film, people talking. Listen to it a couple of times, note every marker, and ask why and how the speaker uses it. The more likeable a speech sample, the fuller it is of these elements (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=750s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 12:30</a>). Do it “not just as an exercise for yourself, but as a favour to yourself” (<a href=\"https://www.youtube.com/watch?v=ZXWMfaRd-AI&amp;t=870s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 14:30</a>).</p>\n</div></section>\n<h2 id=\"innovation-in-vocabulary\">Innovation in vocabulary</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>Building vocabulary is more than collecting a stock of words: it is a <strong>process</strong>, much like the processes of grammar (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=30s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 0:30</a>). The running theme of the lecture is the <strong>socio-culturally embedded context</strong>: society, culture and context work together, intertwined (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=180s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 3:00</a>). They decide how we make words, which words become <strong>high-frequency</strong> (used often) or <strong>low-frequency</strong> (used rarely), and which we pick for <strong>formal</strong> or <strong>informal</strong> use (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=270s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:30</a>).</p>\n</div></section>\n<h3 id=\"prefixes-and-suffixes-from-greek-and-latin\">Prefixes and suffixes from Greek and Latin</h3>\n<p>English has a very productive pattern: it builds words with prefixes and suffixes from <strong>Greek</strong> and <strong>Latin</strong>, two <strong>classical</strong> (ancient) languages that English has borrowed from for a long time (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=330s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:30</a>). The aim is not a full list but to see the pattern, so that you can find it in the words you meet (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=360s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:00</a>).</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Low-frequency, high-cognitive words</span></div><div class=\"box-b\">\n<p>Words built from Greek and Latin parts are usually <strong>low-frequency</strong> words, and they sit in the <strong>high-cognitive</strong> zone: they need more thinking to understand. “The higher the cognitive level, the lower the frequency” (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=630s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:30</a>). We cannot avoid them in academic English and in special fields, and once we know the parts, their meaning becomes easier (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=660s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:00</a>).</p>\n</div></section>\n<p>The slides “Prefixes from Greek and Latin” (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=331s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:31</a>, <a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=717s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:57</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Prefix</th>\n<th>Meaning</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>aer-</td>\n<td>air</td>\n<td>aerobic, aeronautics</td>\n</tr>\n<tr>\n<td>geo-</td>\n<td>earth</td>\n<td>geometry, geopolitical, geography</td>\n</tr>\n<tr>\n<td>hemi-</td>\n<td>half</td>\n<td>hemisphere</td>\n</tr>\n<tr>\n<td>herb-</td>\n<td>related to plants</td>\n<td>herbal, herbivorous</td>\n</tr>\n<tr>\n<td>hydro-</td>\n<td>related to water</td>\n<td>hydrogen, hydrochloride</td>\n</tr>\n<tr>\n<td>hyper-</td>\n<td>more, in excess</td>\n<td>hyperactive, hypersensitive</td>\n</tr>\n<tr>\n<td>hypo-</td>\n<td>less</td>\n<td>hypothyroidism</td>\n</tr>\n<tr>\n<td>inter-</td>\n<td>between</td>\n<td>internet, interpersonal</td>\n</tr>\n<tr>\n<td>intra-</td>\n<td>within</td>\n<td>intranet, intracellular</td>\n</tr>\n<tr>\n<td>mega-</td>\n<td>big</td>\n<td>megabyte, mega star</td>\n</tr>\n<tr>\n<td>re-</td>\n<td>back, again</td>\n<td>redo, reuse, rebuild, recycle</td>\n</tr>\n<tr>\n<td>ultra-</td>\n<td>in excess</td>\n<td>ultrasonic, ultraviolet</td>\n</tr>\n</tbody>\n</table></div>\n<p>The slide “Suffixes from Greek and Latin” (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=813s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:33</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Suffix</th>\n<th>Meaning</th>\n<th>Examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>-cide</td>\n<td>killer</td>\n<td>insecticide, pesticide, homicide</td>\n</tr>\n<tr>\n<td>-gamy</td>\n<td>marriage</td>\n<td>polygamy, bigamy</td>\n</tr>\n<tr>\n<td>-gen</td>\n<td>produce</td>\n<td>carcinogen, allergen</td>\n</tr>\n<tr>\n<td>-graph</td>\n<td>writing</td>\n<td>cinematograph, telegraph</td>\n</tr>\n<tr>\n<td>-ism</td>\n<td>act of</td>\n<td>multilingualism, journalism</td>\n</tr>\n<tr>\n<td>-logy</td>\n<td>science of, study of</td>\n<td>biology, anthropology</td>\n</tr>\n<tr>\n<td>-nomy</td>\n<td>knowledge of</td>\n<td>economy, astronomy</td>\n</tr>\n<tr>\n<td>-vore</td>\n<td>feeding</td>\n<td>carnivore, herbivore</td>\n</tr>\n</tbody>\n</table></div>\n<section class=\"box ex\"><div class=\"box-h\"><span class=\"box-k\">Worked example</span><span class=\"box-t\">Reading a word from its parts (my example, with the lecture’s tables)</span></div><div class=\"box-b\">\n<ol>\n<li>Take <em>herbivore</em>. Split it: <em>herb-</em> + <em>-vore</em>.</li>\n<li><em>herb-</em> = related to plants (prefix table).</li>\n<li><em>-vore</em> = feeding (suffix table).</li>\n<li>Put the meanings together: “plant-feeding”. A <em>herbivore</em> is an animal that feeds on plants.</li>\n<li>Now <em>hydrogen</em>: <em>hydro-</em> (water) + <em>-gen</em> (produce) = “water-producer”. Hydrogen burns to make water.</li>\n</ol>\n<p><strong>Answer:</strong> <em>herbivore</em> = an animal that eats plants; <em>hydrogen</em> = literally “water-producer”. Knowing the parts gives the meaning.</p>\n</div></section>\n<h3 id=\"words-from-foreign-languages\">Words from foreign languages</h3>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>English is spoken and used across the world, so it is in <strong>contact</strong> with more languages than any other language: French, German, Spanish and Italian, and also Hindi, Tamil, Telugu, Bangla, Indonesian and Japanese. Hindi is unlikely to meet Spanish directly, but English meets both (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1080s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 18:00</a>). So English borrows from almost every language. In the lecturer’s view, this openness to mixing, and not only the British Empire, is why English became so dynamic and so widely used (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1170s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:30</a>).</p>\n</div></section>\n<p>The slide “Words from Foreign Languages” (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1046s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:26</a>): “Some lexicographers have documented words from as many as <strong>120 languages</strong> in English. Out of them <strong>Latin</strong> is the major source.” (A <strong>lexicographer</strong> writes dictionaries.)</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Languages</th>\n<th>The slide’s examples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Celtic languages</td>\n<td>basket, bachelor, beak, car, cross, clan</td>\n</tr>\n<tr>\n<td>Latin and Greek</td>\n<td>candle, circle, plant, preach, false, mile</td>\n</tr>\n<tr>\n<td>Scandinavian languages</td>\n<td>dirt, egg, kid, leg, skin, sky, window, man, wife</td>\n</tr>\n<tr>\n<td>French</td>\n<td>government, royal, evidence, grammar, logic, dinner, art, lemon</td>\n</tr>\n<tr>\n<td>Hindi and Indian languages</td>\n<td>karma, jungle, loot, thug, pyjamas, juggernaut, avatar, dhoti, sari, dharna</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Celtic</strong> languages include Irish and Welsh; <strong>Scandinavian</strong> languages, from northern Europe, include Norwegian, Swedish and Danish. (Strictly, <em>man</em> and <em>wife</em> were already in Old English; Old Norse, the old Scandinavian language, had very similar words.)</p>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">When is a word really borrowed?</span></div><div class=\"box-b\">\n<p>“The actual borrowing happens when some word comes in the language and are used by speakers of other languages also.” Speakers of Hindi easily notice Hindi words in English, but <em>jungle</em> or <em>loot</em> counts as borrowed because speakers of other languages use it too. Here <strong>foreign</strong> does not mean geography; it means “other than English” (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1380s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:00</a>).</p>\n</div></section>\n<h3 id=\"instilingo-the-code-of-iit-madras\">Instilingo: the code of IIT Madras</h3>\n<section class=\"box df\"><div class=\"box-h\"><span class=\"box-k\">Definition</span><span class=\"box-t\">Instilingo</span></div><div class=\"box-b\">\n<p><em><strong>Instilingo</strong></em> is the term at IIT Madras for the <strong>code</strong> (a variety of language) that its young students use in conversations among themselves (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1410s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:30</a>). It draws words from Hindi, Tamil, Telugu, Malayalam, Kannada and English and uses them in productive patterns. It is innovative, and it creates an association and an identity among the students.</p>\n</div></section>\n<p>The word is itself an example: <em><strong>insti</strong></em> (short for <em>institute</em>) + <em><strong>lingo</strong></em> (short for <em>language</em>) (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1560s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 26:00</a>). The slide (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1432s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:52</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Word (source language)</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>firang / firangs (Hindi)</td>\n<td>foreigners</td>\n</tr>\n<tr>\n<td>junta / juntum (Hindi)</td>\n<td>people</td>\n</tr>\n<tr>\n<td>sutt / sutts (Hindi)</td>\n<td>cigarettes</td>\n</tr>\n<tr>\n<td>chumma (Tamil)</td>\n<td>simply</td>\n</tr>\n<tr>\n<td>kutty (Tamil)</td>\n<td>small</td>\n</tr>\n<tr>\n<td>vetty (Tamil)</td>\n<td>jobless</td>\n</tr>\n<tr>\n<td>enti / entra (Telugu)</td>\n<td>what</td>\n</tr>\n</tbody>\n</table></div>\n<p>Two more patterns from the talk (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1590s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 26:30</a>):</p>\n<ul>\n<li><strong>Shortening</strong>: <em><strong>funda</strong></em>, from <em>fundamental</em>.</li>\n<li><strong>Irony</strong>: <em><strong>gyan</strong></em> literally means “knowledge”, but students use it for unnecessary knowledge, unnecessary information and unnecessary talk (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1620s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 27:00</a>).</li>\n</ul>\n<h3 id=\"new-media\">New media</h3>\n<p>Social media, also called <strong>new media</strong>, has brought words that did not exist 20 or 25 years ago, and new meanings for old words. These are “high frequency words, frequently used and perfectly acceptable English words” (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1710s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 28:30</a>). The slide (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1687s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 28:07</a>): <em>tweet, Facebook, Insta(gram), blog, meme, unfriend, like, share, DP, WhatsApp, follow, troll, subscribe, viral</em>.</p>\n<ul>\n<li><em><strong>Insta</strong></em> comes from <em>Instagram</em> (and <em>-gram</em> is also the end of <em>telegram</em>) (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1740s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 29:00</a>).</li>\n<li><em><strong>Unfriend</strong></em>: there was no such word in the real world; it names breaking the link with someone on a social networking site (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1770s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 29:30</a>).</li>\n<li><em><strong>Like</strong></em>: an old word with a new meaning, the option to show whether you endorse (approve of) something (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1800s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 30:00</a>).</li>\n<li><em><strong>DP</strong></em> (display picture) has become a word; <em><strong>WhatsApp</strong></em> comes from the phrase <em>what’s up</em> (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1830s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 30:30</a>).</li>\n</ul>\n<p>New-media acronyms (the slide, <a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1908s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 31:48</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Acronym</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>GM</td>\n<td>Good morning</td>\n</tr>\n<tr>\n<td>GN</td>\n<td>Good night</td>\n</tr>\n<tr>\n<td>HB</td>\n<td>Happy Birthday</td>\n</tr>\n<tr>\n<td>ASAP</td>\n<td>As soon as possible</td>\n</tr>\n<tr>\n<td>NBD</td>\n<td>No big deal</td>\n</tr>\n<tr>\n<td>LOL</td>\n<td>Laugh out loud</td>\n</tr>\n<tr>\n<td>ROFL</td>\n<td>Roll on the floor and laugh</td>\n</tr>\n<tr>\n<td>DP</td>\n<td>Display picture</td>\n</tr>\n<tr>\n<td>BF / GF</td>\n<td>Boyfriend / Girlfriend</td>\n</tr>\n<tr>\n<td>RIP</td>\n<td>Rest in Peace (written seriously, to express condolence)</td>\n</tr>\n</tbody>\n</table></div>\n<p>Some people say these are only informal words of the younger generation. That may be true, but the point is the <strong>process</strong> by which a form becomes a word, and knowing such words helps us understand people (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=1920s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 32:00</a>).</p>\n<section class=\"box tp\"><div class=\"box-h\"><span class=\"box-k\">Remember</span><span class=\"box-t\">Keep your eyes and ears open</span></div><div class=\"box-b\">\n<p>The lecturer’s exercise: notice such words when people use them around you, and enrich your vocabulary with them and with words like them (<a href=\"https://www.youtube.com/watch?v=hU5teiNueck&amp;t=2070s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 34:30</a>).</p>\n</div></section>\n<h2 id=\"advanced-vocabulary-loanwords\">Advanced vocabulary: loanwords</h2>\n<section class=\"box id\"><div class=\"box-h\"><span class=\"box-k\">The idea</span></div><div class=\"box-b\">\n<p>Learning has two parts: <strong>learning</strong> something, and <strong>learning to use</strong> what we learnt (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=90s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 1:30</a>). We do not use many words every day, but specific contexts need specific words. Loanwords from Latin, French, Italian and Japanese are <strong>advanced vocabulary</strong>: low-frequency words that need a higher level of cognition. Using them more often, especially in formal writing and talks, shows a wider familiarity with English (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=270s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 4:30</a>). Knowing the plain-English counterpart of each also helps (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=330s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:30</a>).</p>\n</div></section>\n<h3 id=\"words-from-latin\">Words from Latin</h3>\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=307s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 5:07</a>). The say-it guides in brackets are mine.</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Word</th>\n<th>Meaning</th>\n<th>The slide’s sentence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>bona fide</strong> (BOH-nuh FY-dee)</td>\n<td>authentic</td>\n<td>She has established her position as a bona fide celebrity.</td>\n</tr>\n<tr>\n<td><strong>de facto</strong> (day FAK-toh)</td>\n<td>existing, but not (officially) accepted</td>\n<td>He has established himself as the de facto leader of the party.</td>\n</tr>\n<tr>\n<td><strong>impromptu</strong> (im-PROMP-tyoo)</td>\n<td>spontaneous, without preparation</td>\n<td>He made an impromptu speech about honour and responsibility.</td>\n</tr>\n<tr>\n<td><strong>quid pro quo</strong> (kwid proh KWOH)</td>\n<td>something for something, in exchange</td>\n<td>The CEO was sued over a quid pro quo sexual harassment case.</td>\n</tr>\n<tr>\n<td><strong>ad hoc</strong> (ad HOK)</td>\n<td>for the time being; for a specific case</td>\n<td>The judge appointed an ad hoc committee to study the project.</td>\n</tr>\n<tr>\n<td><strong>pro rata</strong> (proh RAH-tuh)</td>\n<td>proportionately</td>\n<td>Fees are calculated on a pro rata basis.</td>\n</tr>\n<tr>\n<td><strong>modus operandi</strong> (MOH-dus op-uh-RAN-dee)</td>\n<td>a specific way of doing something</td>\n<td>Bad bosses often have a recognizable modus operandi!</td>\n</tr>\n<tr>\n<td><strong>status quo</strong> (STAY-tus KWOH)</td>\n<td>the current situation</td>\n<td>There is no desire to change the current status quo.</td>\n</tr>\n</tbody>\n</table></div>\n<p>More from the talk:</p>\n<ul>\n<li><em>Bona fide</em> in place of <em>authentic</em> displays a larger familiarity with English, especially in formal writing or a talk (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=390s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 6:30</a>).</li>\n<li><em>De facto</em>: it exists, it is a reality, but it is not fully accepted (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=450s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 7:30</a>).</li>\n<li><em>Quid pro quo</em> means an exchange of favours in general (I do something for you, you do something for me), not only in harassment cases (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=540s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:00</a>).</li>\n<li><em>Ad hoc</em>: temporary, for one specific case, “not really something that is sustainable” (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=570s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 9:30</a>).</li>\n<li><em>Modus operandi</em>: a way of working specific to a group or a person; literally “mode of operating” (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=690s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:30</a>). The lecturer notes that <em>ad hoc</em> and <em>modus operandi</em> are no longer rare: they have become high-frequency words in our social context (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=660s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 11:00</a>).</li>\n</ul>\n<section class=\"box ex\"><div class=\"box-h\"><span class=\"box-k\">Worked example</span><span class=\"box-t\">Pro rata pay (the lecture’s example at <a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=600s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 10:00</a>)</span></div><div class=\"box-b\">\n<ol>\n<li>The agreement: work 6 hours a day for 600 rupees. (The lecturer says “600 hours”, clearly meaning 6.)</li>\n<li>Pay for one hour: <span class=\"nw\"><span class=\"katex\"><span class=\"katex-html\" aria-hidden=\"true\"><span class=\"base\"><span class=\"strut\" style=\"height:0.7278em;vertical-align:-0.0833em;\"></span><span class=\"mord\">600</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span><span class=\"mbin\">÷</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">6</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span><span class=\"mrel\">=</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">100</span></span></span></span></span> rupees.</li>\n<li>You work only 4 hours.</li>\n<li>Pro rata pay: <span class=\"nw\"><span class=\"katex\"><span class=\"katex-html\" aria-hidden=\"true\"><span class=\"base\"><span class=\"strut\" style=\"height:0.7278em;vertical-align:-0.0833em;\"></span><span class=\"mord\">4</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span><span class=\"mbin\">×</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">100</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span><span class=\"mrel\">=</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">400</span></span></span></span></span> rupees.</li>\n</ol>\n<p><strong>Answer:</strong> 400 rupees. <em>Pro rata</em> = in proportion: the pay follows the hours worked. Fees “calculated on a pro rata basis” work the same way.</p>\n</div></section>\n<h3 id=\"words-from-french\">Words from French</h3>\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=755s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 12:35</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Word</th>\n<th>Meaning</th>\n<th>The slide’s sentence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>à la carte</strong> (ah lah KART)</td>\n<td>individual items on a list, which are not part of a pre-decided package</td>\n<td>It was more expensive to eat à la carte.</td>\n</tr>\n<tr>\n<td><strong>faux pas</strong> (foh PAH)</td>\n<td>a socially inappropriate behaviour</td>\n<td>He was a master of the faux pas.</td>\n</tr>\n<tr>\n<td><strong>en masse</strong> (on MASS)</td>\n<td>in a large group, all together</td>\n<td>The people marched en masse.</td>\n</tr>\n<tr>\n<td><strong>chauffeur</strong> (SHOH-fer)</td>\n<td>a driver specifically for a rich person or celebrity</td>\n<td>Her father’s car and chauffeur are waiting.</td>\n</tr>\n<tr>\n<td><strong>déjà vu</strong> (day-zhah VOO)</td>\n<td>a feeling that you have already seen or experienced the current situation</td>\n<td>When the car broke down again, it was déjà vu.</td>\n</tr>\n<tr>\n<td><strong>bouquet</strong> (boo-KAY)</td>\n<td>a bunch of flowers</td>\n<td>She placed a bouquet of roses on the table.</td>\n</tr>\n<tr>\n<td><strong>souvenir</strong> (soo-vuh-NEER)</td>\n<td>something kept as a reminder of a place one has visited</td>\n<td>He bought a model of a red London bus as a souvenir of his trip to London.</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><em>À la carte</em> is a restaurant word: when items are not part of a buffet package, you order them individually, and that costs more (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=810s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 13:30</a>). <em>Restaurant</em> itself is French.</li>\n<li>A <em>chauffeur</em> is a specially assigned driver, not a taxi driver (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=900s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 15:00</a>).</li>\n<li>A <em>bouquet</em> need not be all one kind of flower (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=990s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 16:30</a>).</li>\n</ul>\n<section class=\"box wn\"><div class=\"box-h\"><span class=\"box-k\">Common mistake</span><span class=\"box-t\">Faux pas, not “faux pax”</span></div><div class=\"box-b\">\n<p>The slide spells it “faux pax”; the correct spelling is <em><strong>faux pas</strong></em> (French for “false step”), said <em>foh PAH</em>. The lecturer himself asks you to check its French pronunciation (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=840s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 14:00</a>).</p>\n</div></section>\n<h3 id=\"words-from-italian\">Words from Italian</h3>\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1062s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:42</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Word</th>\n<th>Meaning</th>\n<th>The slide’s sentence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>zucchini</strong> (zoo-KEE-nee)</td>\n<td>a vegetable</td>\n<td>Zucchini grows during summer.</td>\n</tr>\n<tr>\n<td><strong>vendetta</strong></td>\n<td>a long-lasting revenge</td>\n<td>Jim was arrested for acting on a vendetta against the man who killed his wife.</td>\n</tr>\n<tr>\n<td><strong>inferno</strong></td>\n<td>hell; a large fire</td>\n<td>Can you believe a lit cigar started the inferno that consumed the public library?</td>\n</tr>\n<tr>\n<td><strong>pizza</strong></td>\n<td>food item of Italian origin</td>\n<td>She cancelled her order for a pizza.</td>\n</tr>\n<tr>\n<td><strong>pasta</strong></td>\n<td>food item of Italian origin</td>\n<td>Pour the sauce over the pasta.</td>\n</tr>\n</tbody>\n</table></div>\n<p><em>Pizza</em> and <em>pasta</em> are common words all over the world because the foods are (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1050s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 17:30</a>). In the <em>inferno</em> sentence a small thing, a lit cigar, grows into a huge fire (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1170s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 19:30</a>).</p>\n<h3 id=\"words-from-japanese\">Words from Japanese</h3>\n<p>The slide (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1206s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 20:06</a>):</p>\n<div class=\"tbl\"><table>\n<thead>\n<tr>\n<th>Word</th>\n<th>Meaning</th>\n<th>The slide’s sentence</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>typhoon, tsunami</strong> (tsoo-NAH-mee)</td>\n<td>natural phenomena: a typhoon is a violent tropical storm; a tsunami is a huge sea wave after an earthquake</td>\n<td>After the earthquake shook the ocean, a tsunami wave roared towards the coastline.</td>\n</tr>\n<tr>\n<td><strong>karaoke</strong> (ka-ree-OH-kee)</td>\n<td>sing-along songs</td>\n<td>If you have a karaoke machine, we can have even more fun.</td>\n</tr>\n<tr>\n<td><strong>anime</strong> (AN-ih-may)</td>\n<td>Japanese-style cartoons</td>\n<td>The anime consists of 50 episodes.</td>\n</tr>\n<tr>\n<td><strong>emoji</strong> (ih-MOH-jee)</td>\n<td>digital images expressing emotions</td>\n<td>The emoji’s primary function is to fill in emotional cues otherwise missing from typed conversations.</td>\n</tr>\n<tr>\n<td><strong>karate, judo, sumo</strong></td>\n<td>martial art forms of Japan</td>\n<td>Tony is good at judo and sumo.</td>\n</tr>\n<tr>\n<td><strong>ninja</strong></td>\n<td>a Japanese sword fighter; a person highly skilled in a particular activity</td>\n<td>The BSc programme of IIT Madras will produce a lot of ninja programmers.</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>A tsunami is “really large, not ordinary tide”, and destructive; <em>tsunami</em> is now also used for anything with a very large impact or damage (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1260s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 21:00</a>).</li>\n<li>Emojis add flavour to messages; they belong to informal contexts, not formal ones (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1350s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 22:30</a>).</li>\n<li>In <em>ninja programmers</em>, <em>ninja</em> describes <em>programmers</em> like an adjective: highly skilled (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1410s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 23:30</a>).</li>\n</ul>\n<section class=\"box nt\"><div class=\"box-h\"><span class=\"box-k\">Note</span><span class=\"box-t\">No complete list</span></div><div class=\"box-b\">\n<p>No list of all the words English took from Japanese, or from any other language, exists, and none is possible: language is dynamic, and a list made today would change tomorrow. Knowing some of them opens space to keep looking for more, and to understand the contexts they are used in (<a href=\"https://www.youtube.com/watch?v=pBpCNFpgzXQ&amp;t=1440s\" target=\"_blank\" rel=\"noopener\" class=\"vid\">▶ 24:00</a>).</p>\n</div></section>\n<h2 id=\"summary\">Summary</h2>\n<section class=\"box sm\"><div class=\"box-h\"><span class=\"box-k\">In short</span></div><div class=\"box-b\">\n<ul>\n<li><strong>Quantifiers</strong> (11.1, 11.2): determiners that tell <strong>how many</strong> (countable nouns) or <strong>how much</strong> (uncountable nouns). Before a noun they work like adjectives; alone, like pronouns (<em>No, there aren’t any</em>). They combine with other determiners (<em>all the four eggs</em>).</li>\n<li><strong>Large</strong>: <em>many</em> + countable, <em>much</em> + uncountable (natural in questions and negatives; formal in affirmatives); <em>a lot of, lots of</em> + both. Also <em>not many</em> (= few), <em>many of, as many as, in as many, very / so / a great / too many; so much, much of, too much, as much as, much more, this / that much</em>.</li>\n<li><strong>Small</strong>: <em>a few</em> (countable) and <em>a little</em> (uncountable) = some, positive; <em>few, little</em> = hardly any, negative. <em>A little</em> also modifies (<em>a little more, a little bit difficult</em>); <em>a bit</em> softens (<em>a bit bored</em>).</li>\n<li><strong>Sufficient</strong>: <em>enough, plenty (of)</em>, then <em>heaps of, loads of, a load of</em>, in rising intensity.</li>\n<li><strong>Non-specific</strong>: <em>some</em> in affirmatives; <em>any</em> in negatives and questions (✗ <em>I have any money</em>).</li>\n<li><em><strong>All (of)</strong></em> = everyone, everything (<em>all of you</em>); <em><strong>no</strong></em> = zero; <em><strong>more</strong></em> = additional; <em><strong>most</strong></em> = majority (<em>of</em> only before <em>the</em> or a place name); <em><strong>less</strong></em> = a reduced amount (after a verb: <em>cost less</em>); <em><strong>several</strong></em> = more than one but not many (countable only).</li>\n<li><strong>Two things</strong>: <em>both</em> + plural verb; <em>either</em> (one of two) and <em>neither</em> (not one of two) + singular verb. <em><strong>Each, every</strong></em> + singular verb; <em>every</em> also for regular intervals (<em>every ten minutes</em>).</li>\n<li><strong>Contrast words</strong> (11.3): <em>but</em> (the simplest); <em>although</em> (formal), <em>though</em> (informal), <em>even though</em> (stronger: disappointment) + a clause, at the start or in the middle; what follows them is in focus. <em>However</em> = <em>but</em>, formal, no contractions. <em>Despite / in spite of</em> + a phrase. Never <em>despite of</em>.</li>\n<li><strong>Morphemes</strong> (11.4): the smallest units with a meaning or a grammatical function. Free: lexical (open class: nouns, verbs, adjectives, adverbs) and functional (closed class: prepositions, conjunctions, articles, demonstratives, auxiliaries, pronouns). Bound: bound roots (<em>-ceive</em>) and affixes (prefixes, suffixes; no infixes in English). <strong>Derivational</strong> affixes make new words (the meaning and/or the class changes); the <strong>eight inflections</strong> (<em>-s</em> on verbs, plural <em>-s</em>, <em>'s</em>, <em>-ed</em>, <em>-en</em>, <em>-ing</em>, <em>-er</em>, <em>-est</em>) keep the class.</li>\n<li><strong>Word formation</strong> (11.5): clipping (back <em>exam</em>, fore <em>phone</em>, middle <em>flu</em>, complex <em>navicert</em>); acronymy (<em>NATO, laser</em>); blending (<em>brunch, cyborg, guesstimate</em>); back-formation (<em>resurrect, prepone</em>); borrowing (<em>loot, robot, yoghurt</em>); coinage (<em>xerox</em>); compounding (<em>lipstick</em>; <em>baby oil</em> is not like <em>mustard oil</em>); inflection (<em>goes</em>); derivation (<em>kindness, modernize</em>).</li>\n<li><strong>Connecting ideas</strong> (11.6): between sentences with adverbs and prepositional phrases (<em>as a result, alternatively, even so</em>); within a sentence with conjunctions (<em>while, so that, even though</em>). Five functions: contrast and concession, cause and result, adding, same time, before and after. Between two clauses: <em>; however,</em>. <em>However</em> + adjective = no matter how.</li>\n<li><strong>Vocabulary</strong> (11.7, 11.8): Greek and Latin parts (<em>aer-, geo-, hemi-, herb-, hydro-, hyper-, hypo-, inter-, intra-, mega-, re-, ultra-; -cide, -gamy, -gen, -graph, -ism, -logy, -nomy, -vore</em>) make low-frequency, high-cognitive words. English has words from about 120 languages. Instilingo (<em>insti</em> + <em>lingo</em>), new-media words and acronyms. Loanwords: Latin (<em>bona fide, de facto, impromptu, quid pro quo, ad hoc, pro rata, modus operandi, status quo</em>), French (<em>à la carte, faux pas, en masse, chauffeur, déjà vu, bouquet, souvenir</em>), Italian (<em>zucchini, vendetta, inferno, pizza, pasta</em>), Japanese (<em>typhoon, tsunami, karaoke, anime, emoji, karate, judo, sumo, ninja</em>).</li>\n</ul>\n</div></section>\n<h2 id=\"check-yourself\">Check yourself</h2>\n<details class=\"ck\"><summary><span class=\"ck-k\">Check yourself</span><span class=\"ck-q\">Fill in <em>a few, few, a little</em> or <em>little</em>, and give the reason: (1) ___ teachers will accompany the students on the trip. (2) ___ apples from the shop were good, so I threw most of them away. (3) Rub ___ moisturizer on the face for hydration. (4) He has ___ knowledge of the subject, so do not trust his advice.</span></summary><div class=\"ck-a\">\n<ol>\n<li><strong>A few</strong>: <em>teachers</em> is countable, and the meaning is positive (some will go).</li>\n<li><strong>Few</strong>: countable, and the meaning is negative (hardly any were good).</li>\n<li><strong>a little</strong>: <em>moisturizer</em> is uncountable; some, a small amount.</li>\n<li><strong>little</strong>: uncountable, and negative (almost no knowledge).</li>\n</ol>\n<p>Sentences (1) to (3) are the lecture’s; the second half of (2) and sentence (4) are mine.</p>\n</div></details>\n<details class=\"ck\"><summary><span class=\"ck-k\">Check yourself</span><span class=\"ck-q\">Correct each sentence: (1) <em>I have any money with me.</em> (2) <em>Most of work has been completed.</em> (3) <em>Neither of the pens were working.</em> (4) <em>Reva bought the car despite of her mother’s objections.</em></span></summary><div class=\"ck-a\">\n<ol>\n<li><em>Any</em> needs a negative or a question: ✓ <em>I have <strong>some</strong> money with me</em>, or ✓ <em>I don’t have <strong>any</strong> money with me.</em></li>\n<li><em>Of</em> comes only before <em>the</em>: ✓ <em>Most work has been completed</em>, or ✓ <em>Most <strong>of the</strong> work has been completed.</em></li>\n<li><em>Neither</em> takes a singular verb: ✓ <em>Neither of the pens <strong>was</strong> working.</em></li>\n<li>Never <em>despite of</em>: ✓ <em>despite her mother’s objections</em>, or ✓ <em>in spite of her mother’s objections.</em></li>\n</ol>\n</div></details>\n<details class=\"ck\"><summary><span class=\"ck-k\">Check yourself</span><span class=\"ck-q\">Break each word into morphemes, and say whether its last affix is derivational or inflectional: <em>nationalization, teaches, unhappy, fastest, worker, taller</em>.</span></summary><div class=\"ck-a\">\n<ul>\n<li><em>nation</em> + <em>-al</em> + <em>-ize</em> + <em>-ation</em>: all <strong>derivational</strong> (noun → adjective → verb → noun).</li>\n<li><em>teach</em> + <em>-es</em>: <strong>inflectional</strong> (third person singular, present tense; still a verb).</li>\n<li><em>un-</em> + <em>happy</em>: <strong>derivational</strong> (a new word with the opposite meaning; still an adjective).</li>\n<li><em>fast</em> + <em>-est</em>: <strong>inflectional</strong> (superlative; still an adjective).</li>\n<li><em>work</em> + <em>-er</em>: <strong>derivational</strong> (verb → noun: a person who works).</li>\n<li><em>tall</em> + <em>-er</em>: <strong>inflectional</strong> (comparative; still an adjective).</li>\n</ul>\n</div></details>\n<details class=\"ck\"><summary><span class=\"ck-k\">Check yourself</span><span class=\"ck-q\">Name the word-formation process behind each word: <em>exam, brunch, NATO, resurrect, xerox, lipstick, flu, loot</em>.</span></summary><div class=\"ck-a\">\n<ul>\n<li><em>exam</em>: <strong>back clipping</strong> (from <em>examination</em>).</li>\n<li><em>brunch</em>: <strong>blending</strong> (<em>breakfast</em> + <em>lunch</em>).</li>\n<li><em>NATO</em>: <strong>acronymy</strong> (North Atlantic Treaty Organisation).</li>\n<li><em>resurrect</em>: <strong>back-formation</strong> (from <em>resurrection</em>, by removing <em>-ion</em>).</li>\n<li><em>xerox</em>: <strong>coinage</strong> (a product name now used for photocopying in general).</li>\n<li><em>lipstick</em>: <strong>compounding</strong> (<em>lip</em> + <em>stick</em>).</li>\n<li><em>flu</em>: <strong>middle clipping</strong> (from <em>influenza</em>).</li>\n<li><em>loot</em>: <strong>borrowing</strong> (from Hindi).</li>\n</ul>\n</div></details>\n<details class=\"ck\"><summary><span class=\"ck-k\">Check yourself</span><span class=\"ck-q\">Join the two sentences, once with <em>even though</em> and once with <em>even so</em>: “Much of the power of trade unions has been lost.” / “Their political influence should not be underestimated.”</span></summary><div class=\"ck-a\">\n<ul>\n<li>With <em><strong>even though</strong></em> (a conjunction; one sentence): <em>Even though much of the power of trade unions has been lost, their political influence should not be underestimated.</em></li>\n<li>With <em><strong>even so</strong></em> (a prepositional phrase; two sentences): <em>Much of the power of trade unions has been lost. Even so, their political influence should not be underestimated.</em></li>\n</ul>\n<p><em>Even though</em> connects ideas <strong>within</strong> a sentence; <em>even so</em> connects them <strong>between</strong> sentences and introduces the surprising fact.</p>\n</div></details>\n<details class=\"ck\"><summary><span class=\"ck-k\">Check yourself</span><span class=\"ck-q\">Which loanword fits? (1) a committee formed only for one project; (2) people who march together in one large group; (3) the feeling “this has happened before”; (4) pay that follows the hours worked. If the full pay is 600 rupees for 6 hours, what is the pay for 3 hours in (4)?</span></summary><div class=\"ck-a\">\n<ol>\n<li><strong>ad hoc</strong> (Latin): an ad hoc committee.</li>\n<li><strong>en masse</strong> (French): they marched en masse.</li>\n<li><strong>déjà vu</strong> (French).</li>\n<li><strong>pro rata</strong> (Latin). Pay for one hour: <span class=\"nw\"><span class=\"katex\"><span class=\"katex-html\" aria-hidden=\"true\"><span class=\"base\"><span class=\"strut\" style=\"height:0.7278em;vertical-align:-0.0833em;\"></span><span class=\"mord\">600</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span><span class=\"mbin\">÷</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">6</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span><span class=\"mrel\">=</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">100</span></span></span></span></span> rupees. Pay for 3 hours: <span class=\"nw\"><span class=\"katex\"><span class=\"katex-html\" aria-hidden=\"true\"><span class=\"base\"><span class=\"strut\" style=\"height:0.7278em;vertical-align:-0.0833em;\"></span><span class=\"mord\">3</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span><span class=\"mbin\">×</span><span class=\"mspace\" style=\"margin-right:0.2222em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">100</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span><span class=\"mrel\">=</span><span class=\"mspace\" style=\"margin-right:0.2778em;\"></span></span><span class=\"base\"><span class=\"strut\" style=\"height:0.6444em;\"></span><span class=\"mord\">300</span></span></span></span></span> rupees.</li>\n</ol>\n</div></details>\n"});
